/**
 * @method
 * @name binance#watchMyLiquidationsForSymbols
 * @description watch the private liquidations of a trading pair
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/user-data-streams/Event-ccxt.Order-Update
 * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/user-data-streams/Event-ccxt.Order-Update
 * @param {string[]} symbols list of unified market symbols
 * @param {int} [since] the earliest time in ms to fetch liquidations for
 * @param {int} [limit] the maximum number of liquidation structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an array of [liquidation structures]{@link https://github.com/ccxt/ccxt/wiki/Manual#liquidation-structure}
 */
func (this *Binance) WatchMyLiquidationsForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchMyLiquidationsForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Binance) watchMyLiquidationsForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	symbols = this.MarketSymbols(symbols, nil, true, true, true)
	var market any = this.GetMarketFromSymbols(symbols)
	var messageHashes []any = []any{"myLiquidations"}
	if !this.IsEmpty(symbols) {
		for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
			var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
			messageHashes = append(messageHashes, "myLiquidations::"+*symbol)
		}
	}
	var typeVar any = nil
	var subType any = nil
	typeVarsubTypeparamsVariable := this.ResolveAuthType("watchMyLiquidationsForSymbols", market, params)
	typeVar = ccxt.GetValue(typeVarsubTypeparamsVariable, 0)
	subType = ccxt.GetValue(typeVarsubTypeparamsVariable, 1)
	params = ccxt.MapTyped(ccxt.GetValue(typeVarsubTypeparamsVariable, 2))
	// hand the resolved type forward: the helper already omitted type and
	// subType from params, so a bare authenticate would re-derive from
	// options.defaultType and seed a different bucket than the listenKey
	// read below indexes - the derive-first shape watchBalance uses

	ccxt.PanicOnError((<-this.AuthenticateAsync(this.Extend(map[string]any{
		"type":    typeVar,
		"subType": subType,
	}, params))))
	var listenKey any = ccxt.GetValue(ccxt.GetValue(this.Options, typeVar), "listenKey")
	var url any = this.GetPrivateWsUrl(typeVar, listenKey)
	var message any = nil

	newLiquidations := (<-this.WatchMultiple(url, messageHashes, message, []any{typeVar}))
	ccxt.PanicOnError(newLiquidations)
	if this.NewUpdates {

		ch <- newLiquidations
		return nil
	}

	ch <- this.FilterBySymbolsSinceLimit(this.Liquidations, symbols, since, limit)
	return nil
}
func (this *Binance) HandleMyLiquidation(client any, message any) {
	//
	//    {
	//        "s":"BTCUSDT",              // Symbol
	//        "c":"TEST",                 // ccxt.Client ccxt.Order Id
	//          // special client order id:
	//          // starts with "autoclose-": liquidation order
	//          // "adl_autoclose": ccxt.ADL auto close order
	//          // "settlement_autoclose-": settlement order for delisting or delivery
	//        "S":"SELL",                 // Side
	//        "o":"TRAILING_STOP_MARKET", // ccxt.Order Type
	//        "f":"GTC",                  // Time in Force
	//        "q":"0.001",                // Original Quantity
	//        "p":"0",                    // Original Price
	//        "ap":"0",                   // Average Price
	//        "sp":"7103.04",             // Stop Price. Please ignore with TRAILING_STOP_MARKET order
	//        "x":"NEW",                  // Execution Type
	//        "X":"NEW",                  // ccxt.Order ccxt.Status
	//        "i":8886774,                // ccxt.Order Id
	//        "l":"0",                    // ccxt.Order Last Filled Quantity
	//        "z":"0",                    // ccxt.Order Filled Accumulated Quantity
	//        "L":"0",                    // Last Filled Price
	//        "N":"USDT",                 // Commission Asset, will not push if no commission
	//        "n":"0",                    // Commission, will not push if no commission
	//        "T":1568879465650,          // ccxt.Order ccxt.Trade Time
	//        "t":0,                      // ccxt.Trade Id
	//        "b":"0",                    // ccxt.Bids Notional
	//        "a":"9.91",                 // Ask Notional
	//        "m":false,                  // Is this trade the maker side?
	//        "R":false,                  // Is this reduce only
	//        "wt":"CONTRACT_PRICE",      // Stop Price Working Type
	//        "ot":"TRAILING_STOP_MARKET",// Original ccxt.Order Type
	//        "ps":"LONG",                // ccxt.Position Side
	//        "cp":false,                 // If Close-All, pushed with conditional order
	//        "AP":"7476.89",             // Activation Price, only puhed with TRAILING_STOP_MARKET order
	//        "cr":"5.0",                 // Callback Rate, only puhed with TRAILING_STOP_MARKET order
	//        "pP": false,                // If price protection is turned on
	//        "si": 0,                    // ignore
	//        "ss": 0,                    // ignore
	//        "rp":"0",                   // Realized Profit of the trade
	//        "V":"EXPIRE_TAKER",         // STP mode
	//        "pm":"OPPONENT",            // Price match mode
	//        "gtd":0                     // TIF GTD order auto cancel time
	//    }
	//
	var orderType *string = this.SafeString(message, "o")
	if orderType == nil || *orderType != "LIQUIDATION" {
		return
	}
	var marketId *string = this.SafeString(message, "s")
	var market map[string]any = this.SafeMarket(marketId, nil, nil, "swap")
	var symbol *string = this.SafeSymbol(marketId, market)
	var liquidation any = this.ParseWsLiquidation(message, market)
	var cache any = this.MyLiquidations
	if ccxt.IsEqual(cache, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "myLiquidationsLimit", 1000)
		cache = ccxt.NewArrayCache(limit)
	}
	cache.(ccxt.Appender).Append(liquidation)
	this.MyLiquidations = cache
	client.(ccxt.ClientInterface).Resolve([]any{liquidation}, "myLiquidations")
	client.(ccxt.ClientInterface).Resolve([]any{liquidation}, "myLiquidations::"+*symbol)
}

