func (this *Binance) fetchOrderBookWsBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var payload map[string]any = map[string]any{
		"symbol": market["id"],
	}
	if limit != nil {
		payload["limit"] = limit
	}
	var marketType any = this.GetMarketType("fetchOrderBookWs", market, params)
	if !ccxt.IsEqual(marketType, "future") {
		panic(ccxt.BadRequest(this.Id + " fetchOrderBookWs only supports swap markets"))
	}
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), marketType)
	var requestId int64 = this.RequestId(url)
	var messageHash string = strconv.FormatInt(requestId, 10)
	var returnRateLimits any = false
	var returnRateLimitsparamsVariable []any = this.HandleOptionBoolAndParams(params, "fetchOrderBookWs", "returnRateLimits", false)
	returnRateLimits = ccxt.GetValue(returnRateLimitsparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(returnRateLimitsparamsVariable, 1))
	payload["returnRateLimits"] = returnRateLimits
	params = ccxt.MapTyped(this.Omit(params, "test"))
	var message map[string]any = map[string]any{
		"id":     messageHash,
		"method": "depth",
		"params": this.SignParams(this.Extend(payload, params)),
	}
	var subscription map[string]any = map[string]any{
		"method": this.HandleFetchOrderBook,
	}

	orderbook := (<-this.Watch(url, messageHash, message, messageHash, subscription))
	ccxt.PanicOnError(orderbook)
	ccxt.AddElementToObject(orderbook, "symbol", market["symbol"])

	ch <- orderbook
	return nil
}
func (this *Binance) HandleFetchOrderBook(client any, message map[string]any) {
	//
	//    {
	//        "id":"51e2affb-0aba-4821-ba75-f2625006eb43",
	//        "status":200,
	//        "result":{
	//            "lastUpdateId":1027024,
	//            "E":1589436922972,
	//            "T":1589436922959,
	//            "bids":[
	//               [
	//                  "4.00000000",
	//                  "431.00000000"
	//               ]
	//            ],
	//            "asks":[
	//               [
	//                  "4.00000200",
	//                  "12.00000000"
	//               ]
	//            ]
	//        }
	//    }
	//
	var messageHash *string = this.SafeString(message, "id")
	var result map[string]any = ccxt.SafeMapTyped(message, "result")
	var timestamp *int64 = this.SafeInteger(result, "T")
	var orderbook map[string]any = this.ParseOrderBook(result, nil, timestamp)
	orderbook["nonce"] = this.SafeInteger2(result, "lastUpdateId", "u")
	client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
}
func (this *Binance) FetchOrderBookSnapshotAsync(client any, message any, subscription any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOrderBookSnapshotBody(ch, client, message, subscription)
	return ch
}
func (this *Binance) fetchOrderBookSnapshotBody(ch chan any, client any, message any, subscription any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = this.SafeString(subscription, "symbol")
	var messageHash any = ccxt.Add("orderbook::", symbol)

	{
		func(this *Binance) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Binance) any {
						// catch block:
						ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
						client.(ccxt.ClientInterface).Reject(e, messageHash)
						return nil
					}(this)
				}
			}()
			// try block:
			var defaultLimit *int64 = this.SafeInteger(this.Options, "watchOrderBookLimit", 1000)
			var typeVar *string = this.SafeString(subscription, "type")
			var limit *int64 = this.SafeInteger(subscription, "limit", defaultLimit)
			var params map[string]any = ccxt.SafeMapTyped(subscription, "params")
			// 3. Get a depth snapshot from https://www.binance.com/api/v1/depth?symbol=BNBBTC&limit=1000 .
			// todo: this is a synch blocking call - make it async
			// default 100, max 1000, valid limits 5, 10, 20, 50, 100, 500, 1000

			snapshot := (<-this.FetchRestOrderBookSafeAsync(symbol, limit, params))
			ccxt.PanicOnError(snapshot)
			if ccxt.IsEqual(this.SafeValue(this.Orderbooks, symbol), nil) {

				return nil
			}
			var orderbook any = this.SafeValue(this.Orderbooks, symbol)
			orderbook.(ccxt.OrderBookInterface).Reset(snapshot)
			// unroll the accumulated deltas
			var messages any = orderbook.(ccxt.OrderBookInterface).GetCache()
			orderbook.(ccxt.OrderBookInterface).SetCache([]any{})
			for i := 0; i < ccxt.GetArrayLength(messages); i++ {
				var messageItem any = ccxt.GetValue(messages, i)
				var U *int64 = this.SafeInteger(messageItem, "U")
				var u *int64 = this.SafeInteger(messageItem, "u")
				if (U == nil) || (u == nil) {
					continue
				}
				var pu *int64 = this.SafeInteger(messageItem, "pu")
				if typeVar != nil && *typeVar == "future" {
					// 4. Drop any event where u is < lastUpdateId in the snapshot
					if ccxt.IsLessThan(u, ccxt.GetValue(orderbook, "nonce")) {
						continue
					}
					// 5. The first processed event should have U <= lastUpdateId AND u >= lastUpdateId
					if (ccxt.IsLessThanOrEqual(U, ccxt.GetValue(orderbook, "nonce"))) && (ccxt.IsGreaterThanOrEqual(u, ccxt.GetValue(orderbook, "nonce"))) || (ccxt.IsEqual(pu, ccxt.GetValue(orderbook, "nonce"))) {
						this.HandleOrderBookMessage(client, messageItem, orderbook)
					}
				} else {
					// 4. Drop any event where u is <= lastUpdateId in the snapshot
					if ccxt.IsLessThanOrEqual(u, ccxt.GetValue(orderbook, "nonce")) {
						continue
					}
					// 5. The first processed event should have U <= lastUpdateId+1 AND u >= lastUpdateId+1
					if (ccxt.IsLessThanOrEqual((ccxt.Subtract(U, 1)), ccxt.GetValue(orderbook, "nonce"))) && (ccxt.IsGreaterThanOrEqual((ccxt.Subtract(u, 1)), ccxt.GetValue(orderbook, "nonce"))) {
						this.HandleOrderBookMessage(client, messageItem, orderbook)
					}
				}
			}
			if symbol != nil {
				ccxt.AddElementToObject(this.Orderbooks, symbol, orderbook)
			}
			client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
			return nil
		}(this)

	}
	return nil
}
func (this *Binance) HandleDelta(bookside any, delta any) {
	var price *float64 = this.SafeFloat(delta, 0)
	var amount *float64 = this.SafeFloat(delta, 1)
	bookside.(ccxt.IOrderBookSide).Store(price, amount)
}
func (this *Binance) HandleDeltas(bookside any, deltas any) {
	for i := 0; i < ccxt.GetArrayLength(deltas); i++ {
		this.HandleDelta(bookside, ccxt.GetValue(deltas, i))
	}
}
func (this *Binance) HandleOrderBookMessage(client any, message any, orderbook any) any {
	var u *int64 = this.SafeInteger(message, "u")
	this.HandleDeltas(ccxt.GetValue(orderbook, "asks"), this.SafeList(message, "a", []any{}))
	this.HandleDeltas(ccxt.GetValue(orderbook, "bids"), this.SafeList(message, "b", []any{}))
	ccxt.AddElementToObject(orderbook, "nonce", u)
	var timestamp *int64 = this.SafeInteger(message, "E")
	ccxt.AddElementToObject(orderbook, "timestamp", timestamp)
	ccxt.AddElementToObject(orderbook, "datetime", this.Iso8601(timestamp))
	return orderbook
}
func (this *Binance) HandleOrderBook(client any, message any) {
	//
	// initial snapshot is fetched with ccxt's fetchOrderBook
	// the feed does not include a snapshot, just the deltas
	//
	//     {
	//         "e": "depthUpdate", // Event type
	//         "E": 1577554482280, // Event time
	//         "s": "BNBBTC", // Symbol
	//         "U": 157, // First update ID in event
	//         "u": 160, // Final update ID in event
	//         "b": [ // bids
	//             [ "0.0024", "10" ], // price, size
	//         ],
	//         "a": [ // asks
	//             [ "0.0026", "100" ], // price, size
	//         ]
	//     }
	//
	var marketId *string = this.SafeString(message, "s")
	// the client url is the authoritative source for the market type — an
	// ambiguous id like BTCUSDT maps to both the spot and the linear swap
	// market, and picking the first match drops the message under the wrong
	// symbol and stalls the orderbook future (delivery/option ids are
	// unique, so the swap hint resolves those correctly too)
	var isSpot any = this.IsSpotUrl(client)
	var marketType string = "swap"
	if isSpot == true {
		marketType = "spot"
	}
	var market map[string]any = this.SafeMarket(marketId, nil, nil, marketType)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "orderbook::" + *symbol
	if !(ccxt.InOp(this.Orderbooks, symbol)) {
		//
		// https://github.com/ccxt/ccxt/issues/6672
		//
		// Sometimes Binance sends the first delta before the subscription
		// confirmation arrives. At that point the orderbook is not
		// initialized yet and the snapshot has not been requested yet
		// therefore it is safe to drop these premature messages.
		//
		return
	}
	var orderbook any = ccxt.GetValue(this.Orderbooks, symbol)
	var nonce *int64 = this.SafeInteger(orderbook, "nonce")
	if nonce == nil {
		// 2. Buffer the events you receive from the stream.
		ccxt.AppendToArray(orderbook.(ccxt.OrderBookInterface).GetCache(), message)
	} else {

		{
			func(this *Binance) (ret_ any) {
				defer func() {
					if e := recover(); e != nil {
						if e == "break" {
							return
						}
						ret_ = func(this *Binance) any {
							// catch block:
							if ccxt.InOp(this.Orderbooks, symbol) {
								ccxt.Remove(this.Orderbooks, symbol)
							}
							if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash) {
								ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
							}
							client.(ccxt.ClientInterface).Reject(e, messageHash)
							return nil
						}(this)
					}
				}()
				// try block:
				var U *int64 = this.SafeInteger(message, "U")
				if U == nil {
					return
				}
				var u *int64 = this.SafeInteger(message, "u")
				if u == nil {
					return
				}
				var pu *int64 = this.SafeInteger(message, "pu")
				if pu == nil {
					// spot
					// 4. Drop any event where u is <= lastUpdateId in the snapshot
					if u != nil && (nonce == nil || *u > *nonce) {
						var timestamp *int64 = this.SafeInteger(orderbook, "timestamp")
						var conditional any = nil
						if timestamp == nil {
							// 5. The first processed event should have U <= lastUpdateId+1 AND u >= lastUpdateId+1
							conditional = (ccxt.IsLessThanOrEqual((ccxt.Subtract(U, 1)), nonce)) && (ccxt.IsGreaterThanOrEqual((ccxt.Subtract(u, 1)), nonce))
						} else {
							// 6. While listening to the stream, each new event's U should be equal to the previous event's u+1.
							conditional = (ccxt.IsEqual((ccxt.Subtract(U, 1)), nonce))
						}
						if conditional == true {
							this.HandleOrderBookMessage(client, message, orderbook)
							if ccxt.IsLessThan(nonce, this.SafeInteger(orderbook, "nonce", 0)) {
								client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
							}
						} else {
							var checksum any = this.HandleOption("watchOrderBook", "checksum", true)
							if checksum == true {
								panic(ccxt.ChecksumError(ccxt.Add(this.Id+" ", this.OrderbookChecksumMessage(symbol))))
							}
						}
					}
				} else {
					// future
					// 4. Drop any event where u is < lastUpdateId in the snapshot
					if nonce == nil || (u != nil && *u >= *nonce) {
						// 5. The first processed event should have U <= lastUpdateId AND u >= lastUpdateId
						// 6. While listening to the stream, each new event's pu should be equal to the previous event's u, otherwise initialize the process from step 3
						if (U == nil || (nonce != nil && *U <= *nonce)) || (pu == nonce || (pu != nil && nonce != nil && *pu == *nonce)) {
							this.HandleOrderBookMessage(client, message, orderbook)
							if ccxt.IsLessThanOrEqual(nonce, this.SafeInteger(orderbook, "nonce", 0)) {
								client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
							}
						} else {
							var checksum any = this.HandleOption("watchOrderBook", "checksum", true)
							if checksum == true {
								panic(ccxt.ChecksumError(ccxt.Add(this.Id+" ", this.OrderbookChecksumMessage(symbol))))
							}
						}
					}
				}
				return nil
			}(this)

		}
	}
}
func (this *Binance) HandleOrderBookSubscription(client any, message any, subscription any) {
	var defaultLimit *int64 = this.SafeInteger(this.Options, "watchOrderBookLimit", 1000)
	// const messageHash = this.safeString (subscription, 'messageHash')
	var symbolOfSubscription *string = this.SafeString(subscription, "symbol")                          // watchOrderBook
	var symbols []any = ccxt.SafeListTypedDefault(subscription, "symbols", []any{symbolOfSubscription}) // watchOrderBookForSymbols
	var limit *int64 = this.SafeInteger(subscription, "limit", defaultLimit)
	// handle list of symbols
	for i := 0; i < len(symbols); i++ {
		var symbol any = func() any {
			if i >= 0 && i < len(symbols) {
				return ccxt.DerefScalar(symbols[i])
			}
			return nil
		}()
		if ccxt.InOp(this.Orderbooks, symbol) {
			ccxt.Remove(this.Orderbooks, symbol)
		}
		ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook(map[string]any{}, limit))
		subscription = this.Extend(subscription, map[string]any{
			"symbol": symbol,
		})
		// fetch the snapshot in a separate async call
		this.Spawn(this.FetchOrderBookSnapshotAsync, client, message, subscription)
	}
}
func (this *Binance) HandleSubscriptionStatus(client any, message any) any {
	//
	//     {
	//         "result": null,
	//         "id": 1574649734450
	//     }
	//
	var id *string = this.SafeString(message, "id")
	var subscriptionsById map[string]any = this.IndexBy(client.(ccxt.ClientInterface).GetSubscriptions(), "id")
	var subscription any = this.SafeDict(subscriptionsById, id, map[string]any{})
	var method any = this.SafeValue(subscription, "method")
	if !ccxt.IsEqual(method, nil) {
		ccxt.CallDynamically(method, client, message, subscription)
	}
	var isUnSubMessage *bool = this.SafeBool(subscription, "unsubscribe", false)
	if isUnSubMessage != nil && *isUnSubMessage == true {
		this.HandleUnSubscription(client, subscription)
	}
	return message
}
func (this *Binance) HandleUnSubscription(client any, subscription any) {
	var messageHashes []any = ccxt.SafeListTyped(subscription, "messageHashes")
	var subMessageHashes []any = ccxt.SafeListTyped(subscription, "subMessageHashes")
	for j := 0; j < len(messageHashes); j++ {
		var unsubHash *string = ccxt.SafeStringPtr(func() any {
			if j >= 0 && j < len(messageHashes) {
				return ccxt.DerefScalar(messageHashes[j])
			}
			return nil
		}())
		var subHash *string = ccxt.SafeStringPtr(func() any {
			if j >= 0 && j < len(subMessageHashes) {
				return ccxt.DerefScalar(subMessageHashes[j])
			}
			return nil
		}())
		this.CleanUnsubscription(ccxt.AsClient(client), subHash, unsubHash)
	}
	this.CleanCache(subscription)
}

/**
 * @method
 * @name binance#watchTradesForSymbols
 * @description get the list of most recent trades for a list of symbols
 * @see https://developers.binance.com/docs/binance-spot-api-docs/websocket-api/market-data-requests#aggregate-trades
 * @see https://developers.binance.com/docs/binance-spot-api-docs/websocket-api/market-data-requests#recent-trades
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/websocket-market-streams/Aggregate-ccxt.Trade-Streams
 * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/websocket-market-streams/Aggregate-ccxt.Trade-Streams
 * @param {string[]} symbols unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.name] the name of the method to call, 'trade' or 'aggTrade', default is 'trade'
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Binance) WatchTradesForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchTradesForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Binance) watchTradesForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	symbols = this.MarketSymbols(symbols, nil, false, true, true)
	var streamHash string = "multipleTrades"
	if !ccxt.IsEqual(symbols, nil) {
		var symbolsLength int = ccxt.GetArrayLength(symbols)
		if symbolsLength > 200 {
			panic(ccxt.BadRequest(this.Id + " watchTradesForSymbols() accepts 200 symbols at most. To watch more symbols call watchTradesForSymbols() multiple times"))
		}
		streamHash += "::" + ccxt.Join(symbols, ",")
	}
	var name any = nil
	var nameparamsVariable []any = this.HandleOptionStringAndParams(params, "watchTradesForSymbols", "name", "trade")
	name = ccxt.GetValue(nameparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(nameparamsVariable, 1))
	params = ccxt.MapTyped(this.Omit(params, "callerMethodName"))
	var firstMarket map[string]any = this.Market(ccxt.GetValue(symbols, 0))
	var typeVar *string = ccxt.SafeStringPtr(firstMarket["type"])
	var isOption *bool = ccxt.SafeBoolPtr(firstMarket["option"])
	if isOption != nil && *isOption == true {
		typeVar = ccxt.SafeStringPtr("option")
	} else if ccxt.GetValue(firstMarket, "contract") == true {
		typeVar = ccxt.SafeStringPtr(func() string {
			if ccxt.GetValue(firstMarket, "linear") == true {
				return "future"
			}
			return "delivery"
		}())
	}
	var messageHashes []any = []any{}
	var subParams []any = []any{}
	if isOption != nil && *isOption == true {
		// eOptions: always subscribe per-underlying (<underlying>@optionTrade)
		// handleTrade filters to the correct symbol via the 's' field
		var seenUnderlyings map[string]any = map[string]any{}
		for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
			var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
			var market map[string]any = this.Market(symbol)
			messageHashes = append(messageHashes, "trade::"+*symbol)
			var baseIdLower *string = this.SafeStringLower(market, "baseId", "")
			var quoteIdLower *string = this.SafeStringLower(market, "quoteId", "")
			var underlying string = *baseIdLower + "" + *quoteIdLower
			if !(func() bool { _, ok := seenUnderlyings[underlying]; return ok }()) {
				seenUnderlyings[underlying] = true
				subParams = append(subParams, underlying+"@optionTrade")
			}
		}
	} else {
		for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
			var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
			var market map[string]any = this.Market(symbol)
			messageHashes = append(messageHashes, "trade::"+*symbol)
			var rawHash any = ccxt.Add(ccxt.Add(market["lowercaseId"], "@"), name)
			subParams = append(subParams, rawHash)
		}
	}
	var query map[string]any = ccxt.MapTyped(this.Omit(params, "type"))
	var subParamsLength int = len(subParams)
	var url any = ccxt.Add(ccxt.Add(this.GetWsUrl(typeVar, this.GetFutureWsCategory(name)), "/"), this.Stream(typeVar, streamHash, subParamsLength))
	var requestId int64 = this.RequestId(url)
	var request map[string]any = map[string]any{
		"method": "SUBSCRIBE",
		"params": subParams,
		"id":     requestId,
	}
	var subscribe map[string]any = map[string]any{
		"id": requestId,
	}

	var trades ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.WatchMultiple(url, messageHashes, this.Extend(request, query), messageHashes, subscribe))))
	if this.NewUpdates {
		var first map[string]any = ccxt.SafeMapTyped(trades, 0)
		var tradeSymbol *string = this.SafeString(first, "symbol")
		limit = ccxt.ToGetsLimit(trades).GetLimit(tradeSymbol, limit)
	}

	ch <- this.FilterBySinceLimit(trades, since, limit, "timestamp", true)
	return nil
}

/**
 * @method
 * @name binance#unWatchTradesForSymbols
 * @description unsubscribes from the trades channel
 * @see https://developers.binance.com/docs/binance-spot-api-docs/websocket-api/market-data-requests#aggregate-trades
 * @see https://developers.binance.com/docs/binance-spot-api-docs/websocket-api/market-data-requests#recent-trades
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/websocket-market-streams/Aggregate-ccxt.Trade-Streams
 * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/websocket-market-streams/Aggregate-ccxt.Trade-Streams
 * @param {string[]} symbols unified symbol of the market to fetch trades for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.name] the name of the method to call, 'trade' or 'aggTrade', default is 'trade'
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Binance) UnWatchTradesForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.unWatchTradesForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Binance) unWatchTradesForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	symbols = this.MarketSymbols(symbols, nil, false, true, true)
	var streamHash string = "multipleTrades"
	if !ccxt.IsEqual(symbols, nil) {
		var symbolsLength int = ccxt.GetArrayLength(symbols)
		if symbolsLength > 200 {
			panic(ccxt.BadRequest(this.Id + " watchTradesForSymbols() accepts 200 symbols at most. To watch more symbols call watchTradesForSymbols() multiple times"))
		}
		streamHash += "::" + ccxt.Join(symbols, ",")
	}
	var name any = nil
	var nameparamsVariable []any = this.HandleOptionStringAndParams(params, "watchTradesForSymbols", "name", "trade")
	name = ccxt.GetValue(nameparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(nameparamsVariable, 1))
	params = ccxt.MapTyped(this.Omit(params, "callerMethodName"))
	var firstMarket map[string]any = this.Market(ccxt.GetValue(symbols, 0))
	var typeVar *string = ccxt.SafeStringPtr(firstMarket["type"])
	var isOption *bool = ccxt.SafeBoolPtr(firstMarket["option"])
	if isOption != nil && *isOption == true {
		typeVar = ccxt.SafeStringPtr("option")
	} else if ccxt.GetValue(firstMarket, "contract") == true {
		typeVar = ccxt.SafeStringPtr(func() string {
			if ccxt.GetValue(firstMarket, "linear") == true {
				return "future"
			}
			return "delivery"
		}())
	}
	var subMessageHashes []any = []any{}
	var subParams []any = []any{}
	var messageHashes []any = []any{}
	if isOption != nil && *isOption == true {
		// eOptions: always subscribe per-underlying (<underlying>@optionTrade)
		// handleTrade filters to the correct symbol via the 's' field
		var seenUnderlyings map[string]any = map[string]any{}
		for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
			var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
			var market map[string]any = this.Market(symbol)
			subMessageHashes = append(subMessageHashes, "trade::"+*symbol)
			messageHashes = append(messageHashes, "unsubscribe:trade:"+*symbol)
			var baseIdLower *string = this.SafeStringLower(market, "baseId", "")
			var quoteIdLower *string = this.SafeStringLower(market, "quoteId", "")
			var underlying string = *baseIdLower + "" + *quoteIdLower
			if !(func() bool { _, ok := seenUnderlyings[underlying]; return ok }()) {
				seenUnderlyings[underlying] = true
				subParams = append(subParams, underlying+"@optionTrade")
			}
		}
	} else {
		for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
			var symbol *string = ccxt.SafeStringPtr(ccxt.GetValue(symbols, i))
			var market map[string]any = this.Market(symbol)
			subMessageHashes = append(subMessageHashes, "trade::"+*symbol)
			messageHashes = append(messageHashes, "unsubscribe:trade:"+*symbol)
			var rawHash any = ccxt.Add(ccxt.Add(market["lowercaseId"], "@"), name)
			subParams = append(subParams, rawHash)
		}
	}
	var query map[string]any = ccxt.MapTyped(this.Omit(params, "type"))
	var subParamsLength int = len(subParams)
	var url any = ccxt.Add(ccxt.Add(this.GetWsUrl(typeVar, this.GetFutureWsCategory(name)), "/"), this.Stream(typeVar, streamHash, subParamsLength))
	var requestId int64 = this.RequestId(url)
	var request map[string]any = map[string]any{
		"method": "UNSUBSCRIBE",
		"params": subParams,
		"id":     requestId,
	}
	var subscription map[string]any = map[string]any{
		"unsubscribe":      true,
		"id":               strconv.FormatInt(requestId, 10),
		"subMessageHashes": subMessageHashes,
		"messageHashes":    messageHashes,
		"symbols":          symbols,
		"topic":            "trades",
	}

	ch <- ccxt.PanicOnError((<-this.WatchMultiple(url, messageHashes, this.Extend(request, query), messageHashes, subscription)))
	return nil
}

