func (this *Binance) fetchPositionsWsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var payload map[string]any = map[string]any{}
	var market any = nil
	symbols = this.MarketSymbols(symbols, "swap", true, true, true)
	if symbols != nil {
		var symbolsLength int = ccxt.GetArrayLength(symbols)
		if symbolsLength == 1 {
			market = this.Market(ccxt.GetValue(symbols, 0))
			payload["symbol"] = ccxt.GetValue(market, "id")
		}
	}
	var typeVar any = this.GetMarketType("fetchPositionsWs", market, params)
	if (symbols == nil) && (ccxt.IsEqual(typeVar, "spot")) {
		// when symbols aren't provide
		// we shouldn't rely on the defaultType
		typeVar = "future"
	}
	if (!ccxt.IsEqual(typeVar, "future")) && (!ccxt.IsEqual(typeVar, "delivery")) {
		panic(ccxt.BadRequest(this.Id + " fetchPositionsWs only supports swap markets"))
	}
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), typeVar)
	var requestId int64 = this.RequestId(url)
	var messageHash string = strconv.FormatInt(requestId, 10)
	var returnRateLimits any = false
	var returnRateLimitsparamsVariable []any = this.HandleOptionBoolAndParams(params, "fetchPositionsWs", "returnRateLimits", false)
	returnRateLimits = ccxt.GetValue(returnRateLimitsparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(returnRateLimitsparamsVariable, 1))
	payload["returnRateLimits"] = returnRateLimits
	var method *string = nil
	var methodparamsVariable []any = this.HandleOptionStringAndParams(params, "fetchPositionsWs", "method", "account.position")
	method = ccxt.SafeStringPtr(ccxt.GetValue(methodparamsVariable, 0))
	params = ccxt.MapTyped(ccxt.GetValue(methodparamsVariable, 1))
	var message map[string]any = map[string]any{
		"id":     messageHash,
		"method": method,
		"params": this.SignParams(this.Extend(payload, params)),
	}
	var subscription map[string]any = map[string]any{
		"method": this.HandlePositionsWs,
	}

	var result ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.Watch(url, messageHash, message, messageHash, subscription))))

	ch <- this.FilterByArrayPositions(result, "symbol", symbols, false)
	return nil
}
func (this *Binance) HandlePositionsWs(client any, message map[string]any) {
	//
	//    {
	//        id: '1',
	//        status: 200,
	//        result: [
	//            {
	//                symbol: 'BTCUSDT',
	//                positionAmt: '-0.014',
	//                entryPrice: '42901.1',
	//                breakEvenPrice: '30138.83333142',
	//                markPrice: '71055.98470333',
	//                unRealizedProfit: '-394.16838584',
	//                liquidationPrice: '137032.02272908',
	//                leverage: '123',
	//                maxNotionalValue: '50000',
	//                marginType: 'cross',
	//                isolatedMargin: '0.00000000',
	//                isAutoAddMargin: 'false',
	//                positionSide: 'BOTH',
	//                notional: '-994.78378584',
	//                isolatedWallet: '0',
	//                updateTime: 1708906343111,
	//                isolated: false,
	//                adlQuantile: 2
	//            },
	//            ...
	//        ]
	//    }
	//
	//
	var messageHash *string = this.SafeString(message, "id")
	var result []any = ccxt.SafeListTyped(message, "result")
	var positions []any = []any{}
	for i := 0; i < len(result); i++ {
		var parsed any = this.ParsePositionRisk(func() any {
			if i >= 0 && i < len(result) {
				return ccxt.DerefScalar(result[i])
			}
			return nil
		}())
		var entryPrice *string = this.SafeString(parsed, "entryPrice")
		if (entryPrice == nil || *entryPrice != "0") && (entryPrice == nil || *entryPrice != "0.0") && (entryPrice == nil || *entryPrice != "0.00000000") {
			positions = append(positions, parsed)
		}
	}
	client.(ccxt.ClientInterface).Resolve(positions, messageHash)
}

/**
 * @method
 * @name binance#watchBalance
 * @description watch balance and get the amount of funds available for trading or funds locked in orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.portfolioMargin] set to true if you would like to watch the balance of a portfolio margin account
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Binance) WatchBalanceAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Binance) watchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	// derive BEFORE authenticating and pass the result in: authenticate
	// re-derives from its own method scope, so without this a method-scoped
	// options.watchBalance.type seeds one bucket while the read below
	// indexes another - the same derive-first shape watchOrders uses
	var typeVar any = nil
	var subType any = nil
	typeVarsubTypeparamsVariable := this.ResolveAuthType("watchBalance", nil, params)
	typeVar = ccxt.GetValue(typeVarsubTypeparamsVariable, 0)
	subType = ccxt.GetValue(typeVarsubTypeparamsVariable, 1)
	params = ccxt.MapTyped(ccxt.GetValue(typeVarsubTypeparamsVariable, 2))

	ccxt.PanicOnError((<-this.AuthenticateAsync(this.Extend(map[string]any{
		"type":    typeVar,
		"subType": subType,
	}, params))))
	var isPortfolioMargin any = nil
	var isPortfolioMarginparamsVariable []any = this.HandleOptionBoolAndParams2(params, "watchBalance", "papi", "portfolioMargin", false)
	isPortfolioMargin = ccxt.GetValue(isPortfolioMarginparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(isPortfolioMarginparamsVariable, 1))
	var url any = ""
	var urlType any = typeVar
	if (ccxt.IsEqual(typeVar, "spot")) || (ccxt.IsEqual(typeVar, "margin")) {
		// route to WebSocket API connection where the user data stream is subscribed
		url = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), "spot")
	} else {
		if isPortfolioMargin == true {
			urlType = "papi"
		} else if ccxt.IsEqual(typeVar, "option") {
			var demoMode *bool = this.SafeBool(this.Options, "enableDemoTrading", false)
			if (demoMode != nil && *demoMode == true) || this.IsSandboxModeEnabled {
				panic(ccxt.NotSupported(this.Id + " watchBalance() does not support option markets in demo/testnet mode"))
			}
			urlType = "optionPrivate"
		}
		url = this.GetPrivateWsUrl(urlType, ccxt.GetValue(ccxt.GetValue(this.Options, typeVar), "listenKey"))
	}
	var client ccxt.ClientInterface = this.Client(url)
	this.SetBalanceCache(client, typeVar, isPortfolioMargin)
	this.SetPositionsCache(client, typeVar, nil, isPortfolioMargin)
	var options map[string]any = ccxt.SafeMapTyped(this.Options, "watchBalance")
	var fetchBalanceSnapshot *bool = this.SafeBool(options, "fetchBalanceSnapshot", false)
	var awaitBalanceSnapshot *bool = this.SafeBool(options, "awaitBalanceSnapshot", true)
	if (fetchBalanceSnapshot != nil && *fetchBalanceSnapshot == true) && (awaitBalanceSnapshot != nil && *awaitBalanceSnapshot == true) {

		ccxt.PanicOnError((<-client.(ccxt.ClientInterface).Future(ccxt.Add(typeVar, ":fetchBalanceSnapshot"))))
	}
	var messageHash any = ccxt.Add(typeVar, ":balance")
	var message any = nil

	ch <- ccxt.PanicOnError((<-this.Watch(url, messageHash, message, typeVar)))
	return nil
}
func (this *Binance) HandleBalance(client any, message any) {
	//
	// sent upon a balance update not related to orders
	//
	//     {
	//         "e": "balanceUpdate",
	//         "E": 1629352505586,
	//         "a": "IOTX",
	//         "d": "0.43750000",
	//         "T": 1629352505585
	//     }
	//
	// sent upon creating or filling an order
	//
	//     {
	//         "e": "outboundAccountPosition", // Event type
	//         "E": 1564034571105,             // Event Time
	//         "u": 1564034571073,             // Time of last account update
	//         "B": [                          // ccxt.Balances Array
	//             {
	//                 "a": "ETH",                 // Asset
	//                 "f": "10000.000000",        // Free
	//                 "l": "0.000000"             // Locked
	//             }
	//         ]
	//     }
	//
	// future/delivery
	//
	//     {
	//         "e": "ACCOUNT_UPDATE",            // Event Type
	//         "E": 1564745798939,               // Event Time
	//         "T": 1564745798938 ,              // ccxt.Transaction
	//         "i": "SfsR",                      // ccxt.Account Alias
	//         "a": {                            // Update Data
	//             "m":"ORDER",                  // Event reason type
	//             "B":[                         // ccxt.Balances
	//                 {
	//                     "a":"BTC",                // Asset
	//                     "wb":"122624.12345678",   // Wallet ccxt.Balance
	//                     "cw":"100.12345678"       // Cross Wallet ccxt.Balance
	//                 },
	//             ],
	//             "P":[
	//                 {
	//                     "s":"BTCUSD_200925",      // Symbol
	//                     "pa":"0",                 // ccxt.Position Amount
	//                     "ep":"0.0",               // Entry Price
	//                     "cr":"200",               // (Pre-fee) Accumulated Realized
	//                     "up":"0",                 // Unrealized PnL
	//                     "mt":"isolated",          // Margin Type
	//                     "iw":"0.00000000",        // Isolated Wallet (if isolated position)
	//                     "ps":"BOTH"               // ccxt.Position Side
	//                 },
	//             ]
	//         }
	//     }
	// externalLockUpdate
	//    {
	//        "e": "externalLockUpdate",  // Event Type
	//        "E": 1581557507324,         // Event Time
	//        "a": "NEO",                 // Asset
	//        "d": "10.00000000",         // Delta
	//        "T": 1581557507268          // ccxt.Transaction Time
	//    }
	//
	var wallet *string = this.SafeString(this.Options, "wallet", "wb") // cw for cross wallet
	// each account is connected to a different endpoint
	var subscriptions any = client.(ccxt.ClientInterface).GetSubscriptions()
	var subscriptionsKeys []string = ccxt.ObjectKeys(subscriptions)
	var accountType any = this.GetAccountTypeFromSubscriptions(subscriptionsKeys)
	var messageHash any = ccxt.Add(accountType, ":balance")
	if ccxt.IsEqual(ccxt.GetValue(this.Balance, accountType), nil) {
		ccxt.AddElementToObject(this.Balance, accountType, map[string]any{})
	}
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), "info", message)
	var event *string = this.SafeString(message, "e")
	if event != nil && *event == "balanceUpdate" {
		var currencyId *string = this.SafeString(message, "a")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		var delta *string = this.SafeString(message, "d")
		if (accountType != nil) && (code != nil) && (ccxt.InOp(ccxt.GetValue(this.Balance, accountType), code)) {
			var previousValue any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Balance, accountType), code), "free")
			if !ccxt.IsString(previousValue) {
				previousValue = ccxt.DerefScalar(this.NumberToString(previousValue))
			}
			account["free"] = ccxt.Precise.StringAdd(previousValue, delta)
		} else {
			account["free"] = delta
		}
		if (accountType != nil) && (code != nil) {
			ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), code, account)
		}
	} else {
		message = this.SafeDict(message, "a", message)
		var B []any = ccxt.SafeListTyped(message, "B")
		if ccxt.IsEqual(B, nil) {
			return
		}
		for i := 0; i < len(B); i++ {
			var entry any = func() any {
				if i >= 0 && i < len(B) {
					return ccxt.DerefScalar(B[i])
				}
				return nil
			}()
			var currencyId *string = this.SafeString(entry, "a")
			var code *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["free"] = this.SafeString(entry, "f")
			account["used"] = this.SafeString(entry, "l")
			account["total"] = this.SafeString(entry, wallet)
			if (accountType != nil) && (code != nil) {
				ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), code, account)
			}
		}
	}
	var timestamp *int64 = this.SafeInteger(message, "E")
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), "timestamp", timestamp)
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), "datetime", this.Iso8601(timestamp))
	ccxt.AddElementToObject(this.Balance, accountType, this.SafeBalance(ccxt.GetValue(this.Balance, accountType)))
	client.(ccxt.ClientInterface).Resolve(ccxt.GetValue(this.Balance, accountType), messageHash)
}
func (this *Binance) GetAccountTypeFromSubscriptions(subscriptions any) any {
	var accountType any = ""
	for i := 0; i < ccxt.GetArrayLength(subscriptions); i++ {
		var subscription *string = ccxt.SafeStringPtr(ccxt.GetValue(subscriptions, i))
		if (subscription != nil && *subscription == "spot") || (subscription != nil && *subscription == "margin") || (subscription != nil && *subscription == "future") || (subscription != nil && *subscription == "delivery") || (subscription != nil && *subscription == "option") {
			accountType = ccxt.DerefScalar(subscription)
			break
		}
	}
	return accountType
}
func (this *Binance) ResolveAuthType(methodName string, optionalArgs ...any) any {
	// the single home for user-data type derivation: market type, subType,
	// and the guarded linear/inverse rewrite. option and stock must keep
	// their own type, or the listenKey bucket, the endpoint dispatch and
	// the stream selection all silently degrade to futures - the guarded
	// sites used to carry seven inline copies of this dance, and the
	// unguarded copies were the bug class behind the option keepalive and
	// stock keepalive fixes
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var typeVar *string = nil
	var typeVarparamsVariable []any = this.HandleMarketTypeAndParams(methodName, market, params)
	typeVar = ccxt.SafeStringPtr(ccxt.GetValue(typeVarparamsVariable, 0))
	params = ccxt.MapTyped(ccxt.GetValue(typeVarparamsVariable, 1))
	var subType *string = nil
	var subTypeparamsVariable []any = this.HandleSubTypeAndParams(methodName, market, params)
	subType = ccxt.SafeStringPtr(ccxt.GetValue(subTypeparamsVariable, 0))
	params = ccxt.MapTyped(ccxt.GetValue(subTypeparamsVariable, 1))
	if (typeVar == nil || *typeVar != "option") && (typeVar == nil || *typeVar != "stock") {
		if this.IsLinear(typeVar, subType) {
			typeVar = ccxt.SafeStringPtr("future")
		} else if this.IsInverse(typeVar, subType) {
			typeVar = ccxt.SafeStringPtr("delivery")
		}
	}
	// sites consuming every element unpack this; the two that skip subType
	// index it positionally instead, so no receiver is declared-but-unread
	return []any{typeVar, subType, params}
}
func (this *Binance) GetMarketType(method any, market any, optionalArgs ...any) any {
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var typeVar any = nil
	var typeVarparamsVariable []any = this.HandleMarketTypeAndParams(method, market, params)
	typeVar = ccxt.GetValue(typeVarparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(typeVarparamsVariable, 1))
	var subType *string = nil
	var subTypeparamsVariable []any = this.HandleSubTypeAndParams(method, market, params)
	subType = ccxt.SafeStringPtr(ccxt.GetValue(subTypeparamsVariable, 0))
	params = ccxt.MapTyped(ccxt.GetValue(subTypeparamsVariable, 1))
	if this.IsLinear(typeVar, subType) {
		typeVar = "future"
	} else if this.IsInverse(typeVar, subType) {
		typeVar = "delivery"
	}
	return typeVar
}

/**
 * @method
 * @name binance#createOrderWs
 * @description create a trade order
 * @see https://developers.binance.com/docs/binance-spot-api-docs/websocket-api/trading-requests#place-new-order-trade
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/websocket-api/New-ccxt.Order
 * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/websocket-api
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/websocket-api/New-Algo-ccxt.Order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float|undefined} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} params.test test order, default false
 * @param {boolean} params.returnRateLimits set to true to return rate limit information, default false
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Binance) CreateOrderWsAsync(symbol any, typeVar string, side any, amount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrderWsBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Binance) createOrderWsBody(ch chan any, symbol any, typeVar string, side any, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var price *float64 = ccxt.GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var marketType any = this.GetMarketType("createOrderWs", market, params)
	if (!ccxt.IsEqual(marketType, "spot")) && (!ccxt.IsEqual(marketType, "future")) && (!ccxt.IsEqual(marketType, "delivery")) {
		panic(ccxt.BadRequest(this.Id + " createOrderWs only supports spot or swap markets"))
	}
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), marketType)
	var requestId int64 = this.RequestId(url)
	var messageHash string = strconv.FormatInt(requestId, 10)
	var sor *bool = this.SafeBool2(params, "sor", "SOR", false)
	params = ccxt.MapTyped(this.Omit(params, "sor", "SOR"))
	var triggerPrice *string = this.SafeString2(params, "triggerPrice", "stopPrice")
	var stopLossPrice *string = this.SafeString(params, "stopLossPrice", triggerPrice)
	var takeProfitPrice *string = this.SafeString(params, "takeProfitPrice")
	var trailingDelta *string = this.SafeString(params, "trailingDelta")
	var trailingPercent *string = this.SafeStringN(params, []any{"trailingPercent", "callbackRate", "trailingDelta"})
	var isTrailingPercentOrder bool = (trailingPercent != nil)
	var isStopLoss bool = (stopLossPrice != nil) || (trailingDelta != nil)
	var isTakeProfit bool = (takeProfitPrice != nil)
	var isTriggerOrder bool = (triggerPrice != nil)
	var isConditional bool = isTriggerOrder || isTrailingPercentOrder || isStopLoss || isTakeProfit
	var payload map[string]any = ccxt.MapTyped(this.CreateOrderRequest(symbol, typeVar, side, amount, price, params))
	var returnRateLimits any = false
	var returnRateLimitsparamsVariable []any = this.HandleOptionBoolAndParams(params, "createOrderWs", "returnRateLimits", false)
	returnRateLimits = ccxt.GetValue(returnRateLimitsparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(returnRateLimitsparamsVariable, 1))
	payload["returnRateLimits"] = returnRateLimits
	var test *bool = this.SafeBool(params, "test", false)
	params = ccxt.MapTyped(this.Omit(params, "test"))
	if (ccxt.GetValue(market, "linear") == true) && (ccxt.GetValue(market, "swap") == true) && isConditional {
		payload["algoType"] = "CONDITIONAL"
	}
	var message map[string]any = map[string]any{
		"id":     messageHash,
		"method": "order.place",
		"params": this.SignParams(this.Extend(payload, params)),
	}
	if test != nil && *test == true {
		if sor != nil && *sor == true {
			message["method"] = "sor.order.test"
		} else {
			message["method"] = "order.test"
		}
	}
	if (ccxt.GetValue(market, "linear") == true) && (ccxt.GetValue(market, "swap") == true) && isConditional {
		message["method"] = "algoOrder.place"
	}
	var subscription map[string]any = map[string]any{
		"method": this.HandleOrderWs,
	}

	ch <- ccxt.PanicOnError((<-this.Watch(url, messageHash, message, messageHash, subscription)))
	return nil
}
