func (this *Binance) editOrderWsBody(ch chan any, id any, symbol any, typeVar string, side string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	amount := ccxt.GetArg(optionalArgs, 0, nil)
	_ = amount
	var price *float64 = ccxt.GetArgFloat64Ptr(optionalArgs, 1, nil)
	_ = price
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var marketType any = this.GetMarketType("editOrderWs", market, params)
	if (!ccxt.IsEqual(marketType, "spot")) && (!ccxt.IsEqual(marketType, "future")) && (!ccxt.IsEqual(marketType, "delivery")) {
		panic(ccxt.BadRequest(this.Id + " editOrderWs only supports spot or swap markets"))
	}
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), marketType)
	var requestId int64 = this.RequestId(url)
	var messageHash string = strconv.FormatInt(requestId, 10)
	var isSwap bool = ((ccxt.IsEqual(marketType, "future")) || (ccxt.IsEqual(marketType, "delivery")))
	var payload any = map[string]any{}
	if ccxt.IsEqual(marketType, "spot") {
		payload = this.EditSpotOrderRequest(id, symbol, typeVar, side, amount, price, params)
	} else {
		payload = this.EditContractOrderRequest(id, symbol, typeVar, side, amount, price, params)
	}
	var returnRateLimits any = false
	var returnRateLimitsparamsVariable []any = this.HandleOptionBoolAndParams(params, "editOrderWs", "returnRateLimits", false)
	returnRateLimits = ccxt.GetValue(returnRateLimitsparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(returnRateLimitsparamsVariable, 1))
	ccxt.AddElementToObject(payload, "returnRateLimits", returnRateLimits)
	var message map[string]any = map[string]any{
		"id": messageHash,
		"method": func() string {
			if isSwap {
				return "order.modify"
			}
			return "order.cancelReplace"
		}(),
		"params": this.SignParams(this.Extend(payload, params)),
	}
	var subscription map[string]any = map[string]any{
		"method": this.HandleEditOrderWs,
	}

	ch <- ccxt.PanicOnError((<-this.Watch(url, messageHash, message, messageHash, subscription)))
	return nil
}
