/**
 * @method
 * @name binance#cancelOrderWs
 * @description cancel multiple orders
 * @see https://developers.binance.com/docs/binance-spot-api-docs/websocket-api/trading-requests#cancel-order-trade
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/websocket-api/ccxt.Cancel-ccxt.Order
 * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/websocket-api/ccxt.Cancel-ccxt.Order
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/websocket-api/ccxt.Cancel-Algo-ccxt.Order
 * @param {string} id order id
 * @param {string} [symbol] unified market symbol, default is undefined
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string|undefined} [params.cancelRestrictions] Supported values: ONLY_NEW - ccxt.Cancel will succeed if the order status is NEW. ONLY_PARTIALLY_FILLED - ccxt.Cancel will succeed if order status is PARTIALLY_FILLED.
 * @param {boolean} [params.trigger] set to true if you would like to cancel a conditional order
 * @returns {object} an list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Binance) CancelOrderWsAsync(id any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.cancelOrderWsBody(ch, id, optionalArgs...)
	return ch
}
func (this *Binance) cancelOrderWsBody(ch chan any, id any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	if symbol == nil {
		panic(ccxt.BadRequest(this.Id + " cancelOrderWs requires a symbol"))
	}
	var market map[string]any = this.Market(symbol)
	var typeVar any = this.GetMarketType("cancelOrderWs", market, params)
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), typeVar)
	var requestId int64 = this.RequestId(url)
	var messageHash string = strconv.FormatInt(requestId, 10)
	var returnRateLimits any = false
	var returnRateLimitsparamsVariable []any = this.HandleOptionBoolAndParams(params, "cancelOrderWs", "returnRateLimits", false)
	returnRateLimits = ccxt.GetValue(returnRateLimitsparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(returnRateLimitsparamsVariable, 1))
	var payload map[string]any = map[string]any{
		"symbol":           this.MarketId(symbol),
		"returnRateLimits": returnRateLimits,
	}
	var isConditional *bool = this.SafeBoolN(params, []any{"stop", "trigger", "conditional"})
	var clientOrderId *string = this.SafeStringN(params, []any{"clientAlgoId", "origClientOrderId", "clientOrderId"})
	var shouldUseAlgoOrder bool = (ccxt.GetValue(market, "linear") == true) && (ccxt.GetValue(market, "swap") == true) && (isConditional != nil && *isConditional == true)
	if clientOrderId != nil {
		if shouldUseAlgoOrder == true {
			payload["clientAlgoId"] = clientOrderId
		} else {
			payload["origClientOrderId"] = clientOrderId
		}
	} else {
		if shouldUseAlgoOrder == true {
			payload["algoId"] = this.NumberToString(id)
		} else {
			payload["orderId"] = this.NumberToString(id)
		}
	}
	params = ccxt.MapTyped(this.Omit(params, []any{"origClientOrderId", "clientOrderId", "stop", "trigger", "conditional"}))
	var message map[string]any = map[string]any{
		"id":     messageHash,
		"method": "order.cancel",
		"params": this.SignParams(this.Extend(payload, params)),
	}
	if shouldUseAlgoOrder == true {
		message["method"] = "algoOrder.cancel"
	}
	var subscription map[string]any = map[string]any{
		"method": this.HandleOrderWs,
	}

	ch <- ccxt.PanicOnError((<-this.Watch(url, messageHash, message, messageHash, subscription)))
	return nil
}

