/**
 * @method
 * @name binance#watchOrders
 * @description watches information on multiple orders made by the user
 * @see https://developers.binance.com/docs/binance-spot-api-docs/user-data-stream#order-update
 * @see https://developers.binance.com/docs/margin_trading/trade-data-stream/Event-ccxt.Order-Update
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/user-data-streams/Event-ccxt.Order-Update
 * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/user-data-streams/Event-Algo-ccxt.Order-Update
 * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/ws-streams/user-streams#order-report-stream
 * @param {string} symbol unified market symbol of the market the orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.stock] set to true to use stocks user data streams
 * @param {string|undefined} [params.marginMode] 'cross' or 'isolated', for spot margin
 * @param {boolean} [params.portfolioMargin] set to true if you would like to watch portfolio margin account orders
 * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Binance) WatchOrdersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Binance) watchOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbol := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var stock bool = false
	var stockparamsVariable []any = this.HandleOptionBoolAndParams(params, "watchOrders", "stock", false)
	stock = ccxt.GetValueBool(stockparamsVariable, 0, false)
	params = ccxt.MapTyped(ccxt.GetValue(stockparamsVariable, 1))
	if stock {
		// literal on top: a stray type in the caller params must not override
		// the forced stock, the removed authenticateStock ignored it entirely

		ccxt.PanicOnError((<-this.AuthenticateAsync(this.Extend(params, map[string]any{
			"type": "stock",
		}))))
		var stockOptions map[string]any = ccxt.SafeMapTyped(this.Options, "stock")
		var stockListenKey *string = this.SafeString(stockOptions, "listenKey")
		if stockListenKey == nil {
			panic(ccxt.BadRequest(this.Id + " watchOrders() failed to initialize stock listenKey"))
		}
		var stockUrl any = this.GetStockWsUrl("user")
		var stockStreamName string = *stockListenKey + "@orderReport"
		var stockRequestId int64 = this.RequestId(stockUrl)
		var stockMessageHash any = "orders"
		if symbol != nil {
			stockMessageHash = ccxt.Add("orders:", this.Symbol(symbol))
		}
		var stockRequest map[string]any = map[string]any{
			"method": "SUBSCRIBE",
			"params": []any{stockStreamName},
			"id":     stockRequestId,
		}
		var stockQuery map[string]any = ccxt.MapTyped(this.Omit(params, []any{"stock", "name", "callerMethodName", "type", "subType", "symbol", "timeframe"}))
		var stockSubscribe map[string]any = map[string]any{
			"id": stockRequestId,
		}

		var stockOrders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.Watch(stockUrl, stockMessageHash, this.Extend(stockRequest, stockQuery), stockMessageHash, stockSubscribe))))
		if this.NewUpdates {
			limit = ccxt.ToGetsLimit(stockOrders).GetLimit(symbol, limit)
		}

		ch <- this.FilterBySymbolSinceLimit(stockOrders, symbol, since, limit, true)
		return nil
	}
	var messageHash any = "orders"
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
		symbol = ccxt.GetValue(market, "symbol")
		messageHash = ccxt.Add(messageHash, ccxt.Add(":", symbol))
	}
	var typeVar any = nil
	var subType any = nil
	typeVarsubTypeparamsVariable := this.ResolveAuthType("watchOrders", market, params)
	typeVar = ccxt.GetValue(typeVarsubTypeparamsVariable, 0)
	subType = ccxt.GetValue(typeVarsubTypeparamsVariable, 1)
	params = ccxt.MapTyped(ccxt.GetValue(typeVarsubTypeparamsVariable, 2))
	params = this.Extend(params, map[string]any{
		"type":    typeVar,
		"symbol":  symbol,
		"subType": subType,
	}) // needed inside authenticate for isolated margin

	ccxt.PanicOnError((<-this.AuthenticateAsync(params)))
	var marginMode *string = nil
	var marginModeparamsVariable []any = this.HandleMarginModeAndParams("watchOrders", params)
	marginMode = ccxt.SafeStringPtr(ccxt.GetValue(marginModeparamsVariable, 0))
	params = ccxt.MapTyped(ccxt.GetValue(marginModeparamsVariable, 1))
	var urlType any = typeVar
	if (ccxt.IsEqual(typeVar, "margin")) || ((ccxt.IsEqual(typeVar, "spot")) && (marginMode != nil)) {
		urlType = "spot" // spot-margin shares the same stream as regular spot
	}
	var isPortfolioMargin any = nil
	var isPortfolioMarginparamsVariable []any = this.HandleOptionBoolAndParams2(params, "watchOrders", "papi", "portfolioMargin", false)
	isPortfolioMargin = ccxt.GetValue(isPortfolioMarginparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(isPortfolioMarginparamsVariable, 1))
	var url any = ""
	if (ccxt.IsEqual(typeVar, "spot")) || (ccxt.IsEqual(typeVar, "margin")) {
		// route orders to ws-api user data stream
		url = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), "spot")
	} else {
		if isPortfolioMargin == true {
			urlType = "papi"
		} else if ccxt.IsEqual(typeVar, "option") {
			var demoMode *bool = this.SafeBool(this.Options, "enableDemoTrading", false)
			if (demoMode != nil && *demoMode == true) || this.IsSandboxModeEnabled {
				panic(ccxt.NotSupported(this.Id + " watchOrders() does not support option markets in demo/testnet mode"))
			}
			urlType = "optionPrivate"
		}
		url = this.GetPrivateWsUrl(urlType, ccxt.GetValue(ccxt.GetValue(this.Options, typeVar), "listenKey"))
	}
	var client ccxt.ClientInterface = this.Client(url)
	this.SetBalanceCache(client, typeVar, isPortfolioMargin)
	this.SetPositionsCache(client, typeVar, nil, isPortfolioMargin)
	var message any = nil

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.Watch(url, messageHash, message, typeVar))))
	if this.NewUpdates {
		limit = ccxt.ToGetsLimit(orders).GetLimit(symbol, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(orders, symbol, since, limit, true)
	return nil
}
func (this *Binance) ParseWsOrder(order any, optionalArgs ...any) any {
	//
	// spot
	//
	//     {
	//         "e": "executionReport",        // Event type
	//         "E": 1499405658658,            // Event time
	//         "s": "ETHBTC",                 // Symbol
	//         "c": "mUvoqJxFIILMdfAW5iGSOW", // ccxt.Client order ID
	//         "S": "BUY",                    // Side
	//         "o": "LIMIT",                  // ccxt.Order type
	//         "f": "GTC",                    // Time in force
	//         "q": "1.00000000",             // ccxt.Order quantity
	//         "p": "0.10264410",             // ccxt.Order price
	//         "P": "0.00000000",             // Stop price
	//         "F": "0.00000000",             // Iceberg quantity
	//         "g": -1,                       // OrderListId
	//         "C": null,                     // Original client order ID; This is the ID of the order being canceled
	//         "x": "NEW",                    // Current execution type
	//         "X": "NEW",                    // Current order status
	//         "r": "NONE",                   // ccxt.Order reject reason; will be an error code.
	//         "i": 4293153,                  // ccxt.Order ID
	//         "l": "0.00000000",             // Last executed quantity
	//         "z": "0.00000000",             // Cumulative filled quantity
	//         "L": "0.00000000",             // Last executed price
	//         "n": "0",                      // Commission amount
	//         "N": null,                     // Commission asset
	//         "T": 1499405658657,            // ccxt.Transaction time
	//         "t": -1,                       // ccxt.Trade ID
	//         "I": 8641984,                  // Ignore
	//         "w": true,                     // Is the order on the book?
	//         "m": false,                    // Is this trade the maker side?
	//         "M": false,                    // Ignore
	//         "O": 1499405658657,            // ccxt.Order creation time
	//         "Z": "0.00000000",             // Cumulative quote asset transacted quantity
	//         "Y": "0.00000000"              // Last quote asset transacted quantity (i.e. lastPrice * lastQty),
	//         "Q": "0.00000000"              // Quote ccxt.Order Qty
	//     }
	//
	// future
	//
	//     {
	//         "s":"BTCUSDT",                 // Symbol
	//         "c":"TEST",                    // ccxt.Client ccxt.Order Id
	//                                        // special client order id:
	//                                        // starts with "autoclose-": liquidation order
	//                                        // "adl_autoclose": ccxt.ADL auto close order
	//         "S":"SELL",                    // Side
	//         "o":"TRAILING_STOP_MARKET",    // ccxt.Order Type
	//         "f":"GTC",                     // Time in Force
	//         "q":"0.001",                   // Original Quantity
	//         "p":"0",                       // Original Price
	//         "ap":"0",                      // Average Price
	//         "sp":"7103.04",                // Stop Price. Please ignore with TRAILING_STOP_MARKET order
	//         "x":"NEW",                     // Execution Type
	//         "X":"NEW",                     // ccxt.Order ccxt.Status
	//         "i":8886774,                   // ccxt.Order Id
	//         "l":"0",                       // ccxt.Order Last Filled Quantity
	//         "z":"0",                       // ccxt.Order Filled Accumulated Quantity
	//         "L":"0",                       // Last Filled Price
	//         "N":"USDT",                    // Commission Asset, will not push if no commission
	//         "n":"0",                       // Commission, will not push if no commission
	//         "T":1568879465651,             // ccxt.Order ccxt.Trade Time
	//         "t":0,                         // ccxt.Trade Id
	//         "b":"0",                       // ccxt.Bids Notional
	//         "a":"9.91",                    // Ask Notional
	//         "m":false,                     // Is this trade the maker side?
	//         "R":false,                     // Is this reduce only
	//         "wt":"CONTRACT_PRICE",         // Stop Price Working Type
	//         "ot":"TRAILING_STOP_MARKET",   // Original ccxt.Order Type
	//         "ps":"LONG",                   // ccxt.Position Side
	//         "cp":false,                    // If Close-All, pushed with conditional order
	//         "AP":"7476.89",                // Activation Price, only puhed with TRAILING_STOP_MARKET order
	//         "cr":"5.0",                    // Callback Rate, only puhed with TRAILING_STOP_MARKET order
	//         "rp":"0"                       // Realized Profit of the trade
	//     }
	//
	// watchOrders: linear swap trigger order
	//
	//     {
	//         "caid":"Q5xaq5EGKgXXa0fD7fs0Ip",     // ccxt.Client Algo Id
	//         "aid":2148719,                       // Algo Id
	//         "at":"CONDITIONAL",                  // Algo Type
	//         "o":"TAKE_PROFIT",                   // ccxt.Order Type
	//         "s":"BNBUSDT",                       // Symbol
	//         "S":"SELL",                          // Side
	//         "ps":"BOTH",                         // ccxt.Position Side
	//         "f":"GTC",                           // Time in force
	//         "q":"0.01",                          // quantity
	//         "X":"CANCELED",                      // Algo status
	//         "ai":"",                             // order id
	//         "ap": "0.00000",                     // avg fill price in matching engine, only display when order is triggered and placed in matching engine
	//         "aq": "0.00000",                     // execuated quantity in matching engine, only display when order is triggered and placed in matching engine
	//         "act": "0",                          // actual order type in matching engine, only display when order is triggered and placed in matching engine
	//         "tp":"750",                          // Trigger price
	//         "p":"750",                           // ccxt.Order Price
	//         "V":"EXPIRE_MAKER",                  // STP mode
	//         "wt":"CONTRACT_PRICE",               // Working type
	//         "pm":"NONE",                         // Price match mode
	//         "cp":false,                          // If Close-All
	//         "pP":false,                          // If price protection is turned on
	//         "R":false,                           // Is this reduce only
	//         "tt":0,                              // Trigger time
	//         "gtd":0,                             // good till time for GTD time in force
	//         "rm": "Reduce Only reject"           // algo order failed reason
	//     }
	//
	// watchOrders: tokenized equities
	//
	//     {
	//         "e": "orderReport",
	//         "E": 1786010067484,
	//         "x": "ORDER_UPDATE",
	//         "i": "6c62d749-b1e5-4559-9747-d4237f55ff26",
	//         "ai": "b0b6dd9d-8b9b-48a9-ba46-b9d54906e415",
	//         "b": "EQ_AAPL",
	//         "q": "USDC",
	//         "S": "buy",
	//         "o": "limit",
	//         "p": 290,
	//         "Q": 0.02,
	//         "N": null,
	//         "fq": 0,
	//         "FN": 0,
	//         "tc": 5.97,
	//         "Z": 0,
	//         "n": "24H",
	//         "s": "new",
	//         "T": 1786010067361,
	//         "U": 1786010067366
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var event *string = this.SafeString(order, "e")
	if event != nil && *event == "orderReport" {
		var baseAssetCode *string = this.SafeString(order, "b")
		var stockBaseSymbol *string = baseAssetCode
		if (stockBaseSymbol != nil) && (func() int {
			if stockBaseSymbol == nil {
				return -1
			}
			return strings.Index(*stockBaseSymbol, "EQ_")
		}() == 0) {
			stockBaseSymbol = ccxt.SafeStringPtr(func() string {
				if stockBaseSymbol == nil {
					return ""
				}
				str := *stockBaseSymbol
				return str[3:]
			}())
		}
		if stockBaseSymbol == nil {
			stockBaseSymbol = this.SafeString(order, "symbol")
		}
		var stockQuote *string = this.SafeString(order, "q", "USDC")
		var stockSymbol any = this.GetStockUnifiedSymbol(stockBaseSymbol, stockQuote)
		var stockRawStatus *string = this.SafeStringLower(order, "s")
		var statuses map[string]any = map[string]any{
			"accepted":         "open",
			"new":              "open",
			"partially_filled": "open",
			"filled":           "closed",
			"canceled":         "canceled",
			"rejected":         "rejected",
			"expired":          "expired",
		}
		var stockStatus *string = this.SafeString(statuses, stockRawStatus, stockRawStatus)
		var stockAmount *string = this.SafeString(order, "Q")
		var stockFilled *string = this.SafeString(order, "fq")
		var stockRemaining *string = nil
		if (stockAmount != nil) && (stockFilled != nil) {
			stockRemaining = ccxt.Precise.StringSub(stockAmount, stockFilled)
		}
		var stockTimestamp *int64 = this.SafeInteger(order, "T")
		var stockLastUpdateTimestamp *int64 = this.SafeInteger(order, "U", stockTimestamp)
		return this.SafeOrder(map[string]any{
			"info":                order,
			"symbol":              stockSymbol,
			"id":                  this.SafeString(order, "i"),
			"timestamp":           stockTimestamp,
			"datetime":            this.Iso8601(stockTimestamp),
			"lastUpdateTimestamp": stockLastUpdateTimestamp,
			"type":                this.ParseOrderTypeByMarket(this.SafeStringLower(order, "o"), "spot"),
			"timeInForce":         nil,
			"postOnly":            nil,
			"reduceOnly":          nil,
			"side":                this.SafeStringLower(order, "S"),
			"price":               this.SafeString(order, "p"),
			"stopPrice":           nil,
			"triggerPrice":        nil,
			"amount":              stockAmount,
			"cost":                this.SafeString(order, "FN"),
			"average":             nil,
			"filled":              stockFilled,
			"remaining":           stockRemaining,
			"status":              stockStatus,
			"fee":                 nil,
			"trades":              nil,
		})
	}
	var executionType *string = this.SafeString(order, "x")
	var marketId *string = this.SafeString(order, "s")
	// futures user-data events carry the position side field, spot ones do not
	var marketType string = "spot"
	if ccxt.InOp(order, "ps") {
		marketType = "contract"
	}
	var symbol *string = this.SafeSymbol(marketId, nil, nil, marketType)
	var timestamp *int64 = this.SafeInteger(order, "O")
	var T *int64 = this.SafeInteger(order, "T")
	var lastTradeTimestamp *int64 = nil
	if (executionType != nil && *executionType == "NEW") || (executionType != nil && *executionType == "AMENDMENT") || (executionType != nil && *executionType == "CANCELED") {
		if timestamp == nil {
			timestamp = T
		}
	} else if executionType != nil && *executionType == "TRADE" {
		lastTradeTimestamp = T
	}
	var lastUpdateTimestamp *int64 = T
	var fee map[string]any = nil
	var feeCost *string = this.SafeString(order, "n")
	if (feeCost != nil) && (ccxt.Precise.StringGt(feeCost, "0")) {
		var feeCurrencyId *string = this.SafeString(order, "N")
		var feeCurrency *string = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurrency,
		}
	}
	var rawStatus *string = this.SafeString(order, "X")
	var status any = this.ParseOrderStatus(rawStatus)
	var clientOrderId *string = this.SafeString2(order, "C", "caid")
	if (clientOrderId == nil) || (ccxt.GetLength(clientOrderId) == 0) {
		clientOrderId = this.SafeString(order, "c")
	}
	var stopPrice *string = this.SafeStringN(order, []any{"P", "sp", "tp"})
	var timeInForce *string = this.SafeString(order, "f")
	if timeInForce != nil && *timeInForce == "GTX" {
		// GTX means "Good Till Crossing" and is an equivalent way of saying Post Only
		timeInForce = ccxt.SafeStringPtr("PO")
	}
	return this.SafeOrder(map[string]any{
		"info":                order,
		"symbol":              symbol,
		"id":                  this.SafeString2(order, "i", "aid"),
		"clientOrderId":       clientOrderId,
		"timestamp":           timestamp,
		"datetime":            this.Iso8601(timestamp),
		"lastTradeTimestamp":  lastTradeTimestamp,
		"lastUpdateTimestamp": lastUpdateTimestamp,
		"type":                this.ParseOrderTypeByMarket(this.SafeStringLower(order, "o"), marketType),
		"timeInForce":         timeInForce,
		"postOnly":            nil,
		"reduceOnly":          this.SafeBool(order, "R"),
		"side":                this.SafeStringLower(order, "S"),
		"price":               this.SafeString(order, "p"),
		"stopPrice":           stopPrice,
		"triggerPrice":        stopPrice,
		"amount":              this.SafeString(order, "q"),
		"cost":                this.SafeString(order, "Z"),
		"average":             this.SafeString(order, "ap"),
		"filled":              this.SafeString(order, "z"),
		"remaining":           nil,
		"status":              status,
		"fee":                 fee,
		"trades":              nil,
	})
}
func (this *Binance) HandleOrderUpdate(client any, message any) {
	//
	// spot
	//
	//     {
	//         "e": "executionReport",        // Event type
	//         "E": 1499405658658,            // Event time
	//         "s": "ETHBTC",                 // Symbol
	//         "c": "mUvoqJxFIILMdfAW5iGSOW", // ccxt.Client order ID
	//         "S": "BUY",                    // Side
	//         "o": "LIMIT",                  // ccxt.Order type
	//         "f": "GTC",                    // Time in force
	//         "q": "1.00000000",             // ccxt.Order quantity
	//         "p": "0.10264410",             // ccxt.Order price
	//         "P": "0.00000000",             // Stop price
	//         "F": "0.00000000",             // Iceberg quantity
	//         "g": -1,                       // OrderListId
	//         "C": null,                     // Original client order ID; This is the ID of the order being canceled
	//         "x": "NEW",                    // Current execution type
	//         "X": "NEW",                    // Current order status
	//         "r": "NONE",                   // ccxt.Order reject reason; will be an error code.
	//         "i": 4293153,                  // ccxt.Order ID
	//         "l": "0.00000000",             // Last executed quantity
	//         "z": "0.00000000",             // Cumulative filled quantity
	//         "L": "0.00000000",             // Last executed price
	//         "n": "0",                      // Commission amount
	//         "N": null,                     // Commission asset
	//         "T": 1499405658657,            // ccxt.Transaction time
	//         "t": -1,                       // ccxt.Trade ID
	//         "I": 8641984,                  // Ignore
	//         "w": true,                     // Is the order on the book?
	//         "m": false,                    // Is this trade the maker side?
	//         "M": false,                    // Ignore
	//         "O": 1499405658657,            // ccxt.Order creation time
	//         "Z": "0.00000000",             // Cumulative quote asset transacted quantity
	//         "Y": "0.00000000"              // Last quote asset transacted quantity (i.e. lastPrice * lastQty),
	//         "Q": "0.00000000"              // Quote ccxt.Order Qty
	//     }
	//
	// future
	//
	//     {
	//         "e":"ORDER_TRADE_UPDATE",           // Event Type
	//         "E":1568879465651,                  // Event Time
	//         "T":1568879465650,                  // Trasaction Time
	//         "o": {
	//             "s":"BTCUSDT",                  // Symbol
	//             "c":"TEST",                     // ccxt.Client ccxt.Order Id
	//                                             // special client order id:
	//                                             // starts with "autoclose-": liquidation order
	//                                             // "adl_autoclose": ccxt.ADL auto close order
	//             "S":"SELL",                     // Side
	//             "o":"TRAILING_STOP_MARKET",     // ccxt.Order Type
	//             "f":"GTC",                      // Time in Force
	//             "q":"0.001",                    // Original Quantity
	//             "p":"0",                        // Original Price
	//             "ap":"0",                       // Average Price
	//             "sp":"7103.04",                 // Stop Price. Please ignore with TRAILING_STOP_MARKET order
	//             "x":"NEW",                      // Execution Type
	//             "X":"NEW",                      // ccxt.Order ccxt.Status
	//             "i":8886774,                    // ccxt.Order Id
	//             "l":"0",                        // ccxt.Order Last Filled Quantity
	//             "z":"0",                        // ccxt.Order Filled Accumulated Quantity
	//             "L":"0",                        // Last Filled Price
	//             "N":"USDT",                     // Commission Asset, will not push if no commission
	//             "n":"0",                        // Commission, will not push if no commission
	//             "T":1568879465651,              // ccxt.Order ccxt.Trade Time
	//             "t":0,                          // ccxt.Trade Id
	//             "b":"0",                        // ccxt.Bids Notional
	//             "a":"9.91",                     // Ask Notional
	//             "m":false,                      // Is this trade the maker side?
	//             "R":false,                      // Is this reduce only
	//             "wt":"CONTRACT_PRICE",          // Stop Price Working Type
	//             "ot":"TRAILING_STOP_MARKET",    // Original ccxt.Order Type
	//             "ps":"LONG",                    // ccxt.Position Side
	//             "cp":false,                     // If Close-All, pushed with conditional order
	//             "AP":"7476.89",                 // Activation Price, only puhed with TRAILING_STOP_MARKET order
	//             "cr":"5.0",                     // Callback Rate, only puhed with TRAILING_STOP_MARKET order
	//             "rp":"0"                        // Realized Profit of the trade
	//         }
	//     }
	//
	// linear swap conditional
	//
	//     {
	//         "e":"ALGO_UPDATE",  // Event Type
	//         "T":1750515742297,  // Event Time
	//         "E":1750515742303,  // ccxt.Transaction Time
	//         "o":{
	//             "caid":"Q5xaq5EGKgXXa0fD7fs0Ip",     // ccxt.Client Algo Id
	//             "aid":2148719,                       // Algo Id
	//             "at":"CONDITIONAL",                  // Algo Type
	//             "o":"TAKE_PROFIT",                   // ccxt.Order Type
	//             "s":"BNBUSDT",                       // Symbol
	//             "S":"SELL",                          // Side
	//             "ps":"BOTH",                         // ccxt.Position Side
	//             "f":"GTC",                           // Time in force
	//             "q":"0.01",                          // quantity
	//             "X":"CANCELED",                      // Algo status
	//             "ai":"",                             // order id
	//             "ap": "0.00000",                     // avg fill price in matching engine, only display when order is triggered and placed in matching engine
	//             "aq": "0.00000",                     // execuated quantity in matching engine, only display when order is triggered and placed in matching engine
	//             "act": "0",                          // actual order type in matching engine, only display when order is triggered and placed in matching engine
	//             "tp":"750",                          // Trigger price
	//             "p":"750",                           // ccxt.Order Price
	//             "V":"EXPIRE_MAKER",                  // STP mode
	//             "wt":"CONTRACT_PRICE",               // Working type
	//             "pm":"NONE",                         // Price match mode
	//             "cp":false,                          // If Close-All
	//             "pP":false,                          // If price protection is turned on
	//             "R":false,                           // Is this reduce only
	//             "tt":0,                              // Trigger time
	//             "gtd":0,                             // good till time for GTD time in force
	//             "rm": "Reduce Only reject"           // algo order failed reason
	//         }
	//     }
	//
	var e *string = this.SafeString(message, "e")
	if e != nil && *e == "orderReport" {
		this.HandleOrder(client, message)
		return
	}
	if (e != nil && *e == "ORDER_TRADE_UPDATE") || (e != nil && *e == "ALGO_UPDATE") {
		var oField any = this.SafeValue(message, "o")
		if ccxt.IsArray(oField) {
			// eOptions format: o is an array of orders with nested fi fills
			this.HandleOptionsOrderUpdate(client, message)
			return
		}
		message = this.SafeDict(message, "o", message)
	}
	this.HandleMyTrade(client, message)
	this.HandleOrder(client, message)
	this.HandleMyLiquidation(client, message)
}
func (this *Binance) HandleStockPrice(client any, message map[string]any) {
	//
	//     {
	//         "rates": [
	//             {
	//                 "s": "JAVA",
	//                 "ac": "EQ_JAVA",
	//                 "p": "83.26",
	//                 "t": 1785959875000,
	//                 "pc": "83.1800",
	//                 "mp": "ON"
	//             },
	//         ],
	//         "e": "price"
	//     }
	//
	var rates []any = ccxt.SafeListTyped(message, "rates")
	var tickers map[string]any = map[string]any{}
	for i := 0; i < len(rates); i++ {
		var rate map[string]any = ccxt.MapTyped(this.SafeDict(rates, i, map[string]any{}))
		var stockSymbol *string = this.SafeString(rate, "s")
		var symbol any = this.GetStockUnifiedSymbol(stockSymbol, "USDC")
		if symbol == nil {
			continue
		}
		var timestamp *int64 = this.SafeInteger(rate, "t")
		var parsed any = this.SafeTicker(map[string]any{
			"symbol":        symbol,
			"timestamp":     timestamp,
			"datetime":      this.Iso8601(timestamp),
			"last":          this.SafeString(rate, "p"),
			"close":         this.SafeString(rate, "p"),
			"previousClose": this.SafeString(rate, "pc"),
			"info":          rate,
		})
		ccxt.AddElementToObject(this.Tickers, symbol, parsed)
		ccxt.AddElementToObject(tickers, symbol, parsed)
		client.(ccxt.ClientInterface).Resolve(parsed, ccxt.Add("stock:price:", symbol))
	}
	client.(ccxt.ClientInterface).Resolve(tickers, "stock:price")
}
func (this *Binance) HandleStockQuote(client any, message map[string]any) {
	var stockSymbol *string = this.SafeString(message, "s")
	var symbol any = this.GetStockUnifiedSymbol(stockSymbol, "USDC")
	if symbol == nil {
		return
	}
	var timestamp *int64 = this.SafeInteger2(message, "E", "T")
	var parsed any = this.SafeTicker(map[string]any{
		"symbol":    symbol,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"bid":       this.SafeString(message, "bp"),
		"ask":       this.SafeString(message, "ap"),
		"bidVolume": this.SafeString(message, "bs"),
		"askVolume": this.SafeString(message, "as"),
		"info":      message,
	})
	ccxt.AddElementToObject(this.Bidsasks, symbol, parsed)
	client.(ccxt.ClientInterface).Resolve(parsed, ccxt.Add("stock:quote:", symbol))
}
func (this *Binance) HandleOptionsOrderUpdate(client any, message any) {
	//
	// eOptions ORDER_TRADE_UPDATE: "o" is an array of orders (not a dict like futures)
	//
	//     {
	//         "e": "ORDER_TRADE_UPDATE",
	//         "E": 1657613775883,
	//         "o": [
	//             {
	//                 "T": 1657613342918,          // order create time
	//                 "t": 1657613342918,          // order last update time
	//                 "s": "BTC-220930-18000-C",   // symbol
	//                 "c": "",                     // client order ID
	//                 "oid": "4611869636869226548", // order ID
	//                 "p": "1993",                 // price
	//                 "q": "1",                    // signed qty (positive = BUY, negative = SELL)
	//                 "S": "PARTIALLY_FILLED",     // status
	//                 "e": "0.1",                  // cumulative filled qty
	//                 "ec": "199.3",               // cumulative filled amount (USDT)
	//                 "f": "2",                    // cumulative fee
	//                 "tif": "GTC",                // time in force
	//                 "oty": "LIMIT",              // order type
	//                 "fi": [
	//                     {
	//                         "t": "20",           // trade ID
	//                         "p": "1993",         // fill price
	//                         "q": "0.1",          // fill qty
	//                         "T": 1657613774336,  // fill time
	//                         "m": "TAKER",        // "TAKER" or "MAKER"
	//                         "f": "0.0002"        // commission (positive) or rebate (negative)
	//                     }
	//                 ]
	//             }
	//         ]
	//     }
	//
	var orders []any = ccxt.SafeListTyped(message, "o")
	for i := 0; i < len(orders); i++ {
		var order map[string]any = ccxt.SafeMapTyped(orders, i)
		var fills []any = ccxt.SafeListTyped(order, "fi")
		var rawQty *string = this.SafeString(order, "q", "0")
		var side string = "BUY"
		if ccxt.Precise.StringLt(rawQty, "0") {
			side = "SELL"
		}
		var absQty *string = ccxt.Precise.StringAbs(rawQty)
		var executionType string = "NEW"
		if len(fills) > 0 {
			executionType = "TRADE"
		}
		// normalize eOptions fields to the flat format parseWsOrder/handleOrder expect
		var normalizedOrder map[string]any = map[string]any{
			"s": this.SafeString(order, "s"),
			"i": this.SafeString(order, "oid"),
			"c": this.SafeString(order, "c"),
			"S": side,
			"o": this.SafeString(order, "oty"),
			"f": this.SafeString(order, "tif"),
			"q": absQty,
			"p": this.SafeString(order, "p"),
			"X": this.SafeString(order, "S"),
			"x": executionType,
			"z": this.SafeString(order, "e"),
			"Z": this.SafeString(order, "ec"),
			"n": this.SafeString(order, "f"),
			"T": this.SafeInteger(order, "t"),
			"O": this.SafeInteger(order, "T"),
		}
		this.HandleOrder(client, normalizedOrder)
		for j := 0; j < len(fills); j++ {
			var fill map[string]any = ccxt.SafeMapTyped(fills, j)
			var isMaker bool = (this.SafeString(fill, "m") != nil && *this.SafeString(fill, "m") == "MAKER")
			// normalize fill fields to the flat format parseWsTrade/handleMyTrade expect
			var normalizedTrade map[string]any = map[string]any{
				"x": "TRADE",
				"s": this.SafeString(order, "s"),
				"t": this.SafeString(fill, "t"),
				"L": this.SafeString(fill, "p"),
				"l": this.SafeString(fill, "q"),
				"T": this.SafeInteger(fill, "T"),
				"m": isMaker,
				"n": this.SafeString(fill, "f"),
				"i": this.SafeString(order, "oid"),
				"S": side,
				"o": this.SafeString(order, "oty"),
			}
			this.HandleMyTrade(client, normalizedTrade)
		}
	}
}

/**
 * @method
 * @name binance#watchPositions
 * @description watch all open positions
 * @param {string[]|undefined} symbols list of unified market symbols
 * @param {number} [since] since timestamp
 * @param {number} [limit] limit
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.portfolioMargin] set to true if you would like to watch positions in a portfolio margin account
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
 */
func (this *Binance) WatchPositionsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Binance) watchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market any = nil
	var messageHash any = ""
	symbols = this.MarketSymbols(symbols)
	if !this.IsEmpty(symbols) {
		market = this.GetMarketFromSymbols(symbols)
		if symbols == nil {
			panic(ccxt.ArgumentsRequired(this.Id + " watchPositions() symbols is required"))
		}
		messageHash = "::" + ccxt.Join(symbols, ",")
	}
	var typeVar any = nil
	var subType any = nil
	typeVarsubTypeparamsVariable := this.ResolveAuthType("watchPositions", market, params)
	typeVar = ccxt.GetValue(typeVarsubTypeparamsVariable, 0)
	subType = ccxt.GetValue(typeVarsubTypeparamsVariable, 1)
	params = ccxt.MapTyped(ccxt.GetValue(typeVarsubTypeparamsVariable, 2))
	// spot and margin have no positions - whatever still RESOLVES to spot
	// or margin after the helper falls through to the derivatives stream
	// matching the subType. requests a defaultSubType already rewrote
	// arrive here as future or delivery and pass untouched, which lands on
	// the same stream the old raw-type ordering produced in every case
	if (ccxt.IsEqual(typeVar, "spot")) || (ccxt.IsEqual(typeVar, "margin")) {
		typeVar = func() string {
			if ccxt.IsEqual(subType, "inverse") {
				return "delivery"
			}
			return "future"
		}()
	}
	// 'option' stays as 'option', don't redirect to 'future' - the helper's
	// guard finally makes this comment true
	var marketTypeObject map[string]any = map[string]any{}
	marketTypeObject["type"] = typeVar
	marketTypeObject["subType"] = subType

	ccxt.PanicOnError((<-this.AuthenticateAsync(this.Extend(marketTypeObject, params))))
	messageHash = ccxt.Add(ccxt.Add(typeVar, ":positions"), messageHash)
	var isPortfolioMargin any = nil
	var isPortfolioMarginparamsVariable []any = this.HandleOptionBoolAndParams2(params, "watchPositions", "papi", "portfolioMargin", false)
	isPortfolioMargin = ccxt.GetValue(isPortfolioMarginparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(isPortfolioMarginparamsVariable, 1))
	var urlType any = typeVar
	if isPortfolioMargin == true {
		urlType = "papi"
	} else if ccxt.IsEqual(typeVar, "option") {
		var demoMode *bool = this.SafeBool(this.Options, "enableDemoTrading", false)
		if (demoMode != nil && *demoMode == true) || this.IsSandboxModeEnabled {
			panic(ccxt.NotSupported(this.Id + " watchPositions() does not support option markets in demo/testnet mode"))
		}
		urlType = "optionPrivate"
	}
	var url any = this.GetPrivateWsUrl(urlType, ccxt.GetValue(ccxt.GetValue(this.Options, typeVar), "listenKey"))
	var client ccxt.ClientInterface = this.Client(url)
	this.SetBalanceCache(client, typeVar, isPortfolioMargin)
	this.SetPositionsCache(client, typeVar, symbols, isPortfolioMargin)
	var fetchPositionsSnapshot any = this.HandleOption("watchPositions", "fetchPositionsSnapshot", true)
	var awaitPositionsSnapshot any = this.HandleOption("watchPositions", "awaitPositionsSnapshot", true)
	var cache any = this.SafeValue(this.Positions, typeVar)
	if (fetchPositionsSnapshot == true) && (awaitPositionsSnapshot == true) && (ccxt.IsEqual(cache, nil)) {

		var snapshot ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-client.(ccxt.ClientInterface).Future(ccxt.Add(typeVar, ":fetchPositionsSnapshot")))))

		ch <- this.FilterBySymbolsSinceLimit(snapshot, symbols, since, limit, true)
		return nil
	}

	newPositions := (<-this.Watch(url, messageHash, nil, typeVar))
	ccxt.PanicOnError(newPositions)
	if this.NewUpdates {

		ch <- newPositions
		return nil
	}

	ch <- this.FilterBySymbolsSinceLimit(cache, symbols, since, limit, true)
	return nil
}
func (this *Binance) SetPositionsCache(client any, typeVar any, optionalArgs ...any) {
	var symbols []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var isPortfolioMargin bool = ccxt.GetArgBool(optionalArgs, 1, false)
	_ = isPortfolioMargin
	if ccxt.IsEqual(typeVar, "spot") {
		return
	}
	if ccxt.IsEqual(this.Positions, nil) {
		this.Positions = map[string]any{}
	}
	if ccxt.InOp(this.Positions, typeVar) {
		return
	}
	var fetchPositionsSnapshot any = this.HandleOption("watchPositions", "fetchPositionsSnapshot", false)
	if fetchPositionsSnapshot == true {
		var messageHash any = ccxt.Add(typeVar, ":fetchPositionsSnapshot")
		if !(ccxt.InOp(client.(ccxt.ClientInterface).GetFutures(), messageHash)) {
			client.(ccxt.ClientInterface).Future(messageHash)
			this.Spawn(this.LoadPositionsSnapshotAsync, client, messageHash, typeVar, isPortfolioMargin)
		}
	} else {
		ccxt.AddElementToObject(this.Positions, typeVar, ccxt.NewArrayCacheBySymbolBySide())
	}
}
func (this *Binance) LoadPositionsSnapshotAsync(client any, messageHash any, typeVar any, isPortfolioMargin any) <-chan any {
	ch := make(chan any, 1)
	go this.loadPositionsSnapshotBody(ch, client, messageHash, typeVar, isPortfolioMargin)
	return ch
}
func (this *Binance) loadPositionsSnapshotBody(ch chan any, client any, messageHash any, typeVar any, isPortfolioMargin any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = map[string]any{
		"type": typeVar,
	}
	if isPortfolioMargin == true {
		params["portfolioMargin"] = true
	}

	positions := (<-this.FetchPositionsAsync(nil, params))
	ccxt.PanicOnError(positions)
	ccxt.AddElementToObject(this.Positions, typeVar, ccxt.NewArrayCacheBySymbolBySide())
	var cache any = ccxt.GetValue(this.Positions, typeVar)
	for i := 0; i < ccxt.GetArrayLength(positions); i++ {
		var position any = ccxt.GetValue(positions, i)
		var contracts *float64 = this.SafeNumber(position, "contracts", 0)
		if (contracts != nil) && (*contracts > 0) {
			cache.(ccxt.Appender).Append(position)
		}
	}
	// don't remove the future from the .futures cache
	if ccxt.InOp(client.(ccxt.ClientInterface).GetFutures(), messageHash) {
		var future any = ccxt.GetValue(client.(ccxt.ClientInterface).GetFutures(), messageHash)
		future.(*ccxt.Future).Resolve(cache)
		client.(ccxt.ClientInterface).Resolve(cache, ccxt.Add(typeVar, ":position"))
	}
	return nil
}
func (this *Binance) HandlePositions(client any, message any) {
	//
	//     {
	//         e: 'ACCOUNT_UPDATE',
	//         T: 1667881353112,
	//         E: 1667881353115,
	//         a: {
	//             B: [{
	//                 a: 'USDT',
	//                 wb: '1127.95750089',
	//                 cw: '1040.82091149',
	//                 bc: '0'
	//             }],
	//             P: [{
	//                 s: 'BTCUSDT',
	//                 pa: '-0.089',
	//                 ep: '19700.03933',
	//                 cr: '-1260.24809979',
	//                 up: '1.53058860',
	//                 mt: 'isolated',
	//                 iw: '87.13658940',
	//                 ps: 'BOTH',
	//                 ma: 'USDT'
	//             }],
	//             m: 'ORDER'
	//         }
	//     }
	//
	// each account is connected to a different endpoint
	// and has exactly one subscriptionhash which is the account type
	var subscriptions any = client.(ccxt.ClientInterface).GetSubscriptions()
	var subscriptionsKeys []string = ccxt.ObjectKeys(subscriptions)
	var accountType any = this.GetAccountTypeFromSubscriptions(subscriptionsKeys)
	if ccxt.IsEqual(this.Positions, nil) {
		this.Positions = map[string]any{}
	}
	if !(ccxt.InOp(this.Positions, accountType)) {
		ccxt.AddElementToObject(this.Positions, accountType, ccxt.NewArrayCacheBySymbolBySide())
	}
	var cache any = ccxt.GetValue(this.Positions, accountType)
	var data map[string]any = ccxt.SafeMapTyped(message, "a")
	var rawPositions []any = ccxt.SafeListTyped(data, "P")
	var newPositions []any = []any{}
	for i := 0; i < len(rawPositions); i++ {
		var rawPosition map[string]any = ccxt.SafeMapTyped(rawPositions, i)
		var position any = this.ParseWsPosition(rawPosition)
		var timestamp *int64 = this.SafeInteger(message, "E")
		ccxt.AddElementToObject(position, "timestamp", timestamp)
		ccxt.AddElementToObject(position, "datetime", this.Iso8601(timestamp))
		newPositions = append(newPositions, position)
		cache.(ccxt.Appender).Append(position)
	}
	var messageHashes []any = ccxt.ArrayTyped(this.FindMessageHashes(ccxt.AsClient(client), ccxt.Add(accountType, ":positions::")))
	for i := 0; i < len(messageHashes); i++ {
		var messageHash *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(messageHashes) {
				return ccxt.DerefScalar(messageHashes[i])
			}
			return nil
		}())
		var parts []string = strings.Split(*messageHash, "::")
		var symbolsString *string = ccxt.SafeStringPtr(ccxt.GetValue(parts, 1))
		var symbols []string = strings.Split(*symbolsString, ",")
		var positions any = this.FilterByArray(newPositions, "symbol", symbols, false)
		if !this.IsEmpty(positions) {
			client.(ccxt.ClientInterface).Resolve(positions, messageHash)
		}
	}
	client.(ccxt.ClientInterface).Resolve(newPositions, ccxt.Add(accountType, ":positions"))
}
func (this *Binance) ParseWsPosition(position map[string]any, optionalArgs ...any) any {
	//
	//     {
	//         "s": "BTCUSDT", // Symbol
	//         "pa": "0", // ccxt.Position Amount
	//         "ep": "0.00000", // Entry Price
	//         "cr": "200", // (Pre-fee) Accumulated Realized
	//         "up": "0", // Unrealized PnL
	//         "mt": "isolated", // Margin Type
	//         "iw": "0.00000000", // Isolated Wallet (if isolated position)
	//         "ps": "BOTH" // ccxt.Position Side
	//     }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "s")
	var contracts *string = this.SafeString(position, "pa")
	var contractsAbs *string = ccxt.Precise.StringAbs(this.SafeString(position, "pa"))
	var positionSide *string = this.SafeStringLower(position, "ps")
	var hedged bool = true
	if positionSide != nil && *positionSide == "both" {
		hedged = false
		if !ccxt.Precise.StringEq(contracts, "0") {
			if ccxt.Precise.StringLt(contracts, "0") {
				positionSide = ccxt.SafeStringPtr("short")
			} else {
				positionSide = ccxt.SafeStringPtr("long")
			}
		}
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      this.SafeSymbol(marketId, nil, nil, "swap"),
		"notional":                    nil,
		"marginMode":                  this.SafeString(position, "mt"),
		"liquidationPrice":            nil,
		"entryPrice":                  this.SafeNumber(position, "ep"),
		"unrealizedPnl":               this.SafeNumber(position, "up"),
		"percentage":                  nil,
		"contracts":                   this.ParseNumber(contractsAbs),
		"contractSize":                nil,
		"markPrice":                   nil,
		"side":                        positionSide,
		"hedged":                      hedged,
		"timestamp":                   nil,
		"datetime":                    nil,
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"collateral":                  nil,
		"initialMargin":               nil,
		"initialMarginPercentage":     nil,
		"leverage":                    nil,
		"marginRatio":                 nil,
	})
}
func (this *Binance) ParseWsOptionsPosition(position any, optionalArgs ...any) any {
	//
	//  from BALANCE_POSITION_UPDATE event P[] array:
	//  {
	//      "s": "BTC-251123-126000-C",  // option symbol
	//      "c": "-0.1000",              // position quantity (negative = short)
	//      "p": "-120.00000000",        // position value (USDT)
	//      "a": "1200.00000000"         // average entry price
	//  }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "s")
	var contracts *string = this.SafeString(position, "c")
	var contractsAbs *string = ccxt.Precise.StringAbs(contracts)
	var side *string = nil
	if contracts != nil {
		if ccxt.Precise.StringLt(contracts, "0") {
			side = ccxt.SafeStringPtr("short")
		} else if ccxt.Precise.StringGt(contracts, "0") {
			side = ccxt.SafeStringPtr("long")
		}
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      this.SafeSymbol(marketId, market, nil, "option"),
		"notional":                    this.SafeString(position, "p"),
		"marginMode":                  nil,
		"liquidationPrice":            nil,
		"entryPrice":                  this.SafeNumber(position, "a"),
		"unrealizedPnl":               nil,
		"percentage":                  nil,
		"contracts":                   this.ParseNumber(contractsAbs),
		"contractSize":                nil,
		"markPrice":                   nil,
		"side":                        side,
		"hedged":                      false,
		"timestamp":                   nil,
		"datetime":                    nil,
		"maintenanceMargin":           nil,
		"maintenanceMarginPercentage": nil,
		"collateral":                  nil,
		"initialMargin":               nil,
		"initialMarginPercentage":     nil,
		"leverage":                    nil,
		"marginRatio":                 nil,
	})
}

