func (this *Binance) HandleTradesWs(client any, message map[string]any) {
	//
	// fetchMyTradesWs
	//
	//    {
	//        "id": "f4ce6a53-a29d-4f70-823b-4ab59391d6e8",
	//        "status": 200,
	//        "result": [
	//            {
	//                "symbol": "BTCUSDT",
	//                "id": 1650422481,
	//                "orderId": 12569099453,
	//                "orderListId": -1,
	//                "price": "23416.10000000",
	//                "qty": "0.00635000",
	//                "quoteQty": "148.69223500",
	//                "commission": "0.00000000",
	//                "commissionAsset": "BNB",
	//                "time": 1660801715793,
	//                "isBuyer": false,
	//                "isMaker": true,
	//                "isBestMatch": true
	//            },
	//            ...
	//        ],
	//    }
	//
	// fetchTradesWs
	//
	//    {
	//        "id": "f4ce6a53-a29d-4f70-823b-4ab59391d6e8",
	//        "status": 200,
	//        "result": [
	//            {
	//                "id": 0,
	//                "price": "0.00005000",
	//                "qty": "40.00000000",
	//                "quoteQty": "0.00200000",
	//                "time": 1500004800376,
	//                "isBuyerMaker": true,
	//                "isBestMatch": true
	//            }
	//            ...
	//        ],
	//    }
	//
	var messageHash *string = this.SafeString(message, "id")
	var result []any = ccxt.SafeListTypedDefault(message, "result", []any{})
	var trades any = this.ParseTrades(result)
	client.(ccxt.ClientInterface).Resolve(trades, messageHash)
}

/**
 * @method
 * @name binance#watchMyTrades
 * @description watches information on multiple trades made by the user
 * @param {string} symbol unified market symbol of the market orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.portfolioMargin] set to true if you would like to watch trades in a portfolio margin account
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
 */
func (this *Binance) WatchMyTradesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Binance) watchMyTradesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbol := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var typeVar any = nil
	var market map[string]any = nil
	if symbol != nil {
		var marketResolved map[string]any = this.Market(symbol)
		market = marketResolved
		symbol = ccxt.GetValue(market, "symbol")
	}
	var subType any = nil
	typeVarsubTypeparamsVariable := this.ResolveAuthType("watchMyTrades", market, params)
	typeVar = ccxt.GetValue(typeVarsubTypeparamsVariable, 0)
	subType = ccxt.GetValue(typeVarsubTypeparamsVariable, 1)
	params = ccxt.MapTyped(ccxt.GetValue(typeVarsubTypeparamsVariable, 2))
	var messageHash any = "myTrades"
	if (symbol != nil) && (!ccxt.IsEqual(market, nil)) {
		symbol = this.Symbol(symbol)
		messageHash = ccxt.Add(messageHash, ccxt.Add(":", symbol))
		params = this.Extend(params, map[string]any{
			"type":   ccxt.GetValue(market, "type"),
			"symbol": symbol,
		})
	}

	ccxt.PanicOnError((<-this.AuthenticateAsync(this.Extend(map[string]any{
		"type":    typeVar,
		"subType": subType,
	}, params))))
	var urlType any = typeVar // we don't change type because the listening key is different
	if ccxt.IsEqual(typeVar, "margin") {
		urlType = "spot" // spot-margin shares the same stream as regular spot
	}
	var isPortfolioMargin any = nil
	var isPortfolioMarginparamsVariable []any = this.HandleOptionBoolAndParams2(params, "watchMyTrades", "papi", "portfolioMargin", false)
	isPortfolioMargin = ccxt.GetValue(isPortfolioMarginparamsVariable, 0)
	params = ccxt.MapTyped(ccxt.GetValue(isPortfolioMarginparamsVariable, 1))
	var url any = ""
	if (ccxt.IsEqual(typeVar, "spot")) || (ccxt.IsEqual(typeVar, "margin")) {
		url = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "ws-api"), "spot")
	} else {
		if isPortfolioMargin == true {
			urlType = "papi"
		} else if ccxt.IsEqual(typeVar, "option") {
			var demoMode *bool = this.SafeBool(this.Options, "enableDemoTrading", false)
			if (demoMode != nil && *demoMode == true) || this.IsSandboxModeEnabled {
				panic(ccxt.NotSupported(this.Id + " watchMyTrades() does not support option markets in demo/testnet mode"))
			}
			urlType = "optionPrivate"
		}
		url = this.GetPrivateWsUrl(urlType, ccxt.GetValue(ccxt.GetValue(this.Options, typeVar), "listenKey"))
	}
	var client ccxt.ClientInterface = this.Client(url)
	this.SetBalanceCache(client, typeVar, isPortfolioMargin)
	this.SetPositionsCache(client, typeVar, nil, isPortfolioMargin)
	var message any = nil

	var trades ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.Watch(url, messageHash, message, typeVar))))
	if this.NewUpdates {
		limit = ccxt.ToGetsLimit(trades).GetLimit(symbol, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(trades, symbol, since, limit, true)
	return nil
}
func (this *Binance) HandleMyTrade(client any, message any) {
	var messageHash string = "myTrades"
	var executionType *string = this.SafeString(message, "x")
	if executionType != nil && *executionType == "TRADE" {
		var trade map[string]any = ccxt.MapTyped(this.ParseWsTrade(message))
		var orderId *string = this.SafeString(trade, "order")
		var tradeFee any = this.SafeDict(trade, "fee", map[string]any{})
		tradeFee = this.Extend(map[string]any{}, tradeFee)
		var symbol *string = this.SafeString(trade, "symbol")
		if (orderId != nil) && !ccxt.IsEqual(tradeFee, nil) && (symbol != nil) {
			var cachedOrders any = this.Orders
			if !ccxt.IsEqual(cachedOrders, nil) {
				var orders any = this.SafeDict(cachedOrders.(*ccxt.ArrayCache).Hashmap, symbol, map[string]any{})
				var order any = this.SafeDict(orders, orderId)
				if !ccxt.IsEqual(order, nil) {
					// accumulate order fees
					var fees any = this.SafeValue(order, "fees")
					var fee any = this.SafeDict(order, "fee")
					if !this.IsEmpty(fees) {
						var insertNewFeeCurrency bool = true
						for i := 0; i < ccxt.GetArrayLength(fees); i++ {
							var orderFee map[string]any = ccxt.MapTyped(ccxt.GetValue(fees, i))
							if this.SafeString(orderFee, "currency") == this.SafeString(tradeFee, "currency") || (this.SafeString(orderFee, "currency") != nil && this.SafeString(tradeFee, "currency") != nil && *this.SafeString(orderFee, "currency") == *this.SafeString(tradeFee, "currency")) {
								var feeCost any = this.Sum(ccxt.GetValue(tradeFee, "cost"), orderFee["cost"])
								var feeCostString any = this.CurrencyToPrecision(ccxt.GetValue(tradeFee, "currency"), feeCost)
								if feeCostString == nil {
									feeCostString = "0"
								}
								ccxt.AddElementToObject(ccxt.GetValue(ccxt.GetValue(order, "fees"), i), "cost", ccxt.ParseFloat(feeCostString))
								insertNewFeeCurrency = false
								break
							}
						}
						if insertNewFeeCurrency {
							retRes552432 := ccxt.GetValue(order, "fees")
							ccxt.AppendToArray(&retRes552432, tradeFee)
						}
					} else if !ccxt.IsEqual(fee, nil) {
						if this.SafeString(fee, "currency") == this.SafeString(tradeFee, "currency") || (this.SafeString(fee, "currency") != nil && this.SafeString(tradeFee, "currency") != nil && *this.SafeString(fee, "currency") == *this.SafeString(tradeFee, "currency")) {
							var feeCost any = this.Sum(ccxt.GetValue(fee, "cost"), ccxt.GetValue(tradeFee, "cost"))
							var feeCostString any = this.CurrencyToPrecision(ccxt.GetValue(tradeFee, "currency"), feeCost)
							if feeCostString == nil {
								feeCostString = "0"
							}
							ccxt.AddElementToObject(ccxt.GetValue(order, "fee"), "cost", ccxt.ParseFloat(feeCostString))
						} else if ccxt.IsEqual(ccxt.GetValue(fee, "currency"), nil) {
							ccxt.AddElementToObject(order, "fee", tradeFee)
						} else {
							ccxt.AddElementToObject(order, "fees", []any{fee, tradeFee})
							ccxt.AddElementToObject(order, "fee", nil)
						}
					} else {
						ccxt.AddElementToObject(order, "fee", tradeFee)
					}
					// save this trade in the order
					var orderTrades any = this.SafeList(order, "trades", []any{})
					ccxt.AppendToArray(&orderTrades, trade)
					ccxt.AddElementToObject(order, "trades", orderTrades)
					// write the updated order back into the cache: php
					// arrays are value types, so the fee/trades mutations
					// above only touched a local copy there — the cache
					// hashmap rows are wired by reference, so this
					// assignment reaches the cached row (and is a no-op
					// in the reference-semantics runtimes)
					ccxt.AddElementToObject(orders, orderId, order)
				}
			}
		}
		if ccxt.IsEqual(this.MyTrades, nil) {
			var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
			this.MyTrades = ccxt.NewArrayCacheBySymbolById(limit)
		}
		var myTrades any = this.MyTrades
		myTrades.(ccxt.Appender).Append(trade)
		client.(ccxt.ClientInterface).Resolve(this.MyTrades, messageHash)
		var messageHashSymbol *string = ccxt.SafeStringPtr(ccxt.Add(messageHash+":", symbol))
		client.(ccxt.ClientInterface).Resolve(this.MyTrades, messageHashSymbol)
	}
}
func (this *Binance) HandleOrder(client any, message any) {
	var parsed map[string]any = ccxt.MapTyped(this.ParseWsOrder(message))
	var symbol *string = this.SafeString(parsed, "symbol")
	var orderId *string = this.SafeString(parsed, "id")
	if symbol != nil {
		if ccxt.IsEqual(this.Orders, nil) {
			var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
			this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
		}
		var cachedOrders any = this.Orders
		var orders map[string]any = ccxt.SafeMapTyped(cachedOrders.(*ccxt.ArrayCache).Hashmap, symbol)
		var order any = this.SafeDict(orders, orderId)
		if !ccxt.IsEqual(order, nil) {
			var fee any = this.SafeValue(order, "fee")
			if !ccxt.IsEqual(fee, nil) {
				parsed["fee"] = fee
			}
			var fees any = this.SafeList(order, "fees")
			if !ccxt.IsEqual(fees, nil) {
				ccxt.AddElementToObject(parsed, "fees", fees)
			}
			parsed["trades"] = this.SafeValue(order, "trades")
			var timestamp *int64 = this.SafeInteger(parsed, "timestamp")
			if timestamp == nil {
				parsed["timestamp"] = this.SafeInteger(order, "timestamp")
				parsed["datetime"] = this.SafeString(order, "datetime")
			}
		}
		cachedOrders.(ccxt.Appender).Append(parsed)
		var messageHash string = "orders"
		var symbolSpecificMessageHash string = "orders:" + *symbol
		client.(ccxt.ClientInterface).Resolve(cachedOrders, messageHash)
		client.(ccxt.ClientInterface).Resolve(cachedOrders, symbolSpecificMessageHash)
	}
}
func (this *Binance) HandleAcountUpdate(client any, message any) {
	this.HandleBalance(client, message)
	this.HandlePositions(client, message)
}
func (this *Binance) HandleOptionsAccountUpdate(client any, message map[string]any) {
	//
	// BALANCE_POSITION_UPDATE (options user data stream)
	//
	//  {
	//      "e": "BALANCE_POSITION_UPDATE",
	//      "E": 1762917544216,   // event time
	//      "T": 1762917544206,   // transaction time
	//      "m": "ORDER",         // reason
	//      "B": [
	//          { "a": "USDT", "b": "10000471.37940900", "bc": "0" }
	//      ],
	//      "P": [
	//          {
	//              "s": "BTC-251123-126000-C",
	//              "c": "-0.1000",
	//              "p": "-120.00000000",
	//              "a": "1200.00000000"
	//          }
	//      ]
	//  }
	//
	// --- balance ---
	var accountType string = "option"
	if ccxt.IsEqual(ccxt.GetValue(this.Balance, accountType), nil) {
		ccxt.AddElementToObject(this.Balance, accountType, map[string]any{})
	}
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), "info", message)
	var B []any = ccxt.SafeListTyped(message, "B")
	for i := 0; i < len(B); i++ {
		var entry map[string]any = ccxt.SafeMapTyped(B, i)
		var currencyId *string = this.SafeString(entry, "a")
		var code *string = this.SafeCurrencyCode(currencyId)
		if code != nil {
			var account map[string]any = this.Account()
			account["total"] = this.SafeString(entry, "b")
			ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), code, account)
		}
	}
	var timestamp *int64 = this.SafeInteger(message, "E")
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), "timestamp", timestamp)
	ccxt.AddElementToObject(ccxt.GetValue(this.Balance, accountType), "datetime", this.Iso8601(timestamp))
	ccxt.AddElementToObject(this.Balance, accountType, this.SafeBalance(ccxt.GetValue(this.Balance, accountType)))
	client.(ccxt.ClientInterface).Resolve(ccxt.GetValue(this.Balance, accountType), accountType+":balance")
	// --- positions ---
	if ccxt.IsEqual(this.Positions, nil) {
		this.Positions = map[string]any{}
	}
	if !(ccxt.InOp(this.Positions, accountType)) {
		ccxt.AddElementToObject(this.Positions, accountType, ccxt.NewArrayCacheBySymbolBySide())
	}
	var cache any = ccxt.GetValue(this.Positions, accountType)
	var P []any = ccxt.SafeListTyped(message, "P")
	var newPositions []any = []any{}
	for i := 0; i < len(P); i++ {
		var rawPosition map[string]any = ccxt.SafeMapTyped(P, i)
		var position any = this.ParseWsOptionsPosition(rawPosition)
		ccxt.AddElementToObject(position, "timestamp", timestamp)
		ccxt.AddElementToObject(position, "datetime", this.Iso8601(timestamp))
		newPositions = append(newPositions, position)
		cache.(ccxt.Appender).Append(position)
	}
	var messageHashes []any = ccxt.ArrayTyped(this.FindMessageHashes(ccxt.AsClient(client), accountType+":positions::"))
	for i := 0; i < len(messageHashes); i++ {
		var messageHash *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(messageHashes) {
				return ccxt.DerefScalar(messageHashes[i])
			}
			return nil
		}())
		var parts []string = strings.Split(*messageHash, "::")
		var symbolsString *string = ccxt.SafeStringPtr(ccxt.GetValue(parts, 1))
		var symbols []string = strings.Split(*symbolsString, ",")
		var positions any = this.FilterByArray(newPositions, "symbol", symbols, false)
		if !this.IsEmpty(positions) {
			client.(ccxt.ClientInterface).Resolve(positions, messageHash)
		}
	}
	client.(ccxt.ClientInterface).Resolve(newPositions, accountType+":positions")
}
func (this *Binance) HandleWsError(client any, message any) {
	//
	//    {
	//        "error": {
	//            "code": 2,
	//            "msg": "Invalid request: invalid stream"
	//        },
	//        "id": 1
	//    }
	//
	var id *string = this.SafeString(message, "id")
	var rejected bool = false
	var error map[string]any = ccxt.MapTyped(this.SafeDict(message, "error", map[string]any{}))
	var code *int64 = this.SafeInteger(error, "code")
	var msg *string = this.SafeString(error, "msg")
	var codeValue int64 = func() int64 {
		if code == nil {
			return 0
		}
		return *code
	}()

	{
		func(this *Binance) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Binance) any {
						// catch block:
						rejected = true
						// private endpoint uses id as messageHash
						client.(ccxt.ClientInterface).Reject(e, id)
						// public endpoint stores messageHash in subscriptions
						var subscriptionKeys []string = ccxt.ObjectKeys(client.(ccxt.ClientInterface).GetSubscriptions())
						for i := 0; i < len(subscriptionKeys); i++ {
							var subscriptionHash string = ccxt.GetValue(subscriptionKeys, i).(string)
							var subscriptionId *string = this.SafeString(ccxt.GetValue(client.(ccxt.ClientInterface).GetSubscriptions(), subscriptionHash), "id")
							var subscription *string = this.SafeString(ccxt.GetValue(client.(ccxt.ClientInterface).GetSubscriptions(), subscriptionHash), "subscription")
							if id == subscriptionId || (id != nil && subscriptionId != nil && *id == *subscriptionId) {
								client.(ccxt.ClientInterface).Reject(e, subscriptionHash)
								if subscription != nil {
									ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), subscription)
								}
							}
						}
						return nil
					}(this)
				}
			}()
			// try block:
			this.HandleErrors(codeValue, msg, client.(ccxt.ClientInterface).GetUrl(), "", map[string]any{}, this.Json(error), error, map[string]any{}, map[string]any{})
			return nil
		}(this)

	}
	if !rejected {
		client.(ccxt.ClientInterface).Reject(message, id)
	}
	// reset connection if 5xx error
	var codeString *string = this.SafeString(error, "code")
	if (codeString != nil) && (ccxt.GetValue(codeString, 0) == "5") {
		client.(ccxt.ClientInterface).Reset(message)
	}
}
func (this *Binance) HandleEventStreamTerminated(client any, message map[string]any) {
	//
	//    {
	//        e: 'eventStreamTerminated',
	//        E: 1757896885229
	//    }
	//
	var event *string = this.SafeString(message, "e")
	var subscriptions any = client.(ccxt.ClientInterface).GetSubscriptions()
	var subscriptionsKeys []string = ccxt.ObjectKeys(subscriptions)
	var accountType any = this.GetAccountTypeFromSubscriptions(subscriptionsKeys)
	if event != nil && *event == "eventStreamTerminated" {
		ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), accountType)
		client.(ccxt.ClientInterface).Reject(message, accountType)
	}
}
func (this *Binance) HandleMessage(client any, message any) {
	// eOptions combined stream endpoints (/public/stream, /market/stream) wrap events as:
	//   { "stream": "<streamName>", "data": { "e": "...", ... } }
	var streamWrapper *string = this.SafeString(message, "stream")
	if streamWrapper != nil {
		message = this.SafeDict(message, "data", message)
	}
	// handle WebSocketAPI
	var eventMsg any = this.SafeDict(message, "event")
	if !ccxt.IsEqual(eventMsg, nil) {
		message = eventMsg
	}
	// handle combined stream wrapper payloads
	var eventData any = this.SafeDict(message, "data")
	if !ccxt.IsEqual(eventData, nil) {
		message = eventData
	}
	var status *string = this.SafeString(message, "status")
	var error any = this.SafeValue(message, "error")
	if (!ccxt.IsEqual(error, nil)) || ((status != nil) && (status == nil || *status != "200")) {
		this.HandleWsError(client, message)
		return
	}
	// user subscription wraps message in subscriptionId and event
	var id *string = this.SafeString(message, "id")
	var subscriptions map[string]any = ccxt.SafeMapTyped(client.(ccxt.ClientInterface).GetSubscriptions(), id)
	var method any = this.SafeValue(subscriptions, "method")
	if !ccxt.IsEqual(method, nil) {
		ccxt.CallDynamically(method, client, message)
		return
	}
	// handle other APIs
	var methods map[string]any = map[string]any{
		"depthUpdate":             this.HandleOrderBook,
		"trade":                   this.HandleTrade,
		"aggTrade":                this.HandleTrade,
		"price":                   this.HandleStockPrice,
		"quote":                   this.HandleStockQuote,
		"optionTrade":             this.HandleTrade,
		"markPrice":               this.HandleMarkPrices,
		"kline":                   this.HandleOHLCV,
		"markPrice_kline":         this.HandleOHLCV,
		"indexPrice_kline":        this.HandleOHLCV,
		"1hTicker@arr":            this.HandleTickers,
		"4hTicker@arr":            this.HandleTickers,
		"1dTicker@arr":            this.HandleTickers,
		"24hrTicker@arr":          this.HandleTickers,
		"24hrMiniTicker@arr":      this.HandleTickers,
		"1hTicker":                this.HandleTickers,
		"4hTicker":                this.HandleTickers,
		"1dTicker":                this.HandleTickers,
		"24hrTicker":              this.HandleTickers,
		"24hrMiniTicker":          this.HandleTickers,
		"markPriceUpdate":         this.HandleMarkPrices,
		"markPriceUpdate@arr":     this.HandleMarkPrices,
		"markPrice@arr":           this.HandleMarkPrices,
		"bookTicker":              this.HandleBidsAsks,
		"outboundAccountPosition": this.HandleBalance,
		"balanceUpdate":           this.HandleBalance,
		"ACCOUNT_UPDATE":          this.HandleAcountUpdate,
		"BALANCE_POSITION_UPDATE": this.HandleOptionsAccountUpdate,
		"executionReport":         this.HandleOrderUpdate,
		"orderReport":             this.HandleOrderUpdate,
		"ORDER_TRADE_UPDATE":      this.HandleOrderUpdate,
		"ALGO_UPDATE":             this.HandleOrderUpdate,
		"forceOrder":              this.HandleLiquidation,
		"eventStreamTerminated":   this.HandleEventStreamTerminated,
		"externalLockUpdate":      this.HandleBalance,
	}
	var event any = ccxt.DerefScalar(this.SafeString(message, "e"))
	if ccxt.IsArray(message) {
		var arrayMessage map[string]any = ccxt.SafeMapTyped(message, 0)
		event = ccxt.Add(this.SafeString(arrayMessage, "e"), "@arr")
	}
	method = this.SafeValue(methods, event)
	if ccxt.IsEqual(method, nil) {
		var requestId *string = this.SafeString(message, "id")
		if requestId != nil {
			this.HandleSubscriptionStatus(client, message)
			return
		}
		// special case for the real-time bookTicker, since it comes without an event identifier
		//
		//     {
		//         "u": 7488717758,
		//         "s": "BTCUSDT",
		//         "b": "28621.74000000",
		//         "B": "1.43278800",
		//         "a": "28621.75000000",
		//         "A": "2.52500800"
		//     }
		//
		if ccxt.IsEqual(event, nil) && (ccxt.InOp(message, "a")) && (ccxt.InOp(message, "b")) {
			this.HandleBidsAsks(client, message)
		}
	} else {
		ccxt.CallDynamically(method, client, message)
	}
}

func NewBinance(userConfig map[string]any) *Binance {
	p := newBinance()
	p.Init(userConfig)
	return p
}

func (this *Binance) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

